-- Node: ap-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Adult Pharyngitis Overview","body":"See [Steps Summary](#/node/ap-steps-summary) for the rapid-action checklist.\n\n**Why it matters:** [1,2]\n- Pharyngitis is one of the top 20 reasons for adult ED visits\n- Most cases are **viral** (~75-80%) and self-limited\n- **Group A Strep (GAS)** causes ~5-15% of adult sore throats — antibiotics shorten symptoms by ~16h and prevent acute rheumatic fever (ARF) and suppurative complications\n- The high-stakes work is identifying **airway-threatening or life-threatening mimics**: peritonsillar/retropharyngeal abscess, Lemierre syndrome, epiglottitis, Ludwig angina, acute HIV\n\n**Diagnostic framework (IDSA + EB Med):** [1,3,5,22]\n1. Triage every sore throat for airway threat and red flags FIRST\n2. Apply Centor/McIsaac to risk-stratify for GAS\n3. Test (rapid antigen) only those with Centor/McIsaac ≥2\n4. Treat confirmed GAS or empirically at high scores per local protocol\n5. Actively scan for dangerous mimics on every visit\n\n**Adult vs peds note:** IDSA does NOT recommend routine back-up culture in adults with negative rapid antigen (high specificity, low post-test probability). Back-up culture IS recommended in children.\n\n**Basis:** IDSA 2012 GAS pharyngitis guideline [1], the IDSA 2025 risk-assessment/scoring update [5], and the AAFP 2024 rapid evidence review [22]. Epidemiology and score performance from Wessels NEJM 2011 [2] and McIsaac JAMA 2004 [3]. The airway/deep-neck mimics named here are covered by EM-specific sources, not by the GAS guidelines; those sources are listed on the Red Flags and Complications/Mimics nodes.","citation":[1,2,3,5,22],"next":"ap-redflags","calculatorLinks":[{"id":"centor-mcisaac-score","label":"Centor/McIsaac Calculator"}],"summary":"Most pharyngitis is viral; GAS 5-15% in adults. Triage first for airway/red flags, then Centor/McIsaac, test if ≥2, treat confirmed GAS. Hunt mimics every visit."}'::jsonb
WHERE id = 'ap-start' AND tree_id = 'adult-pharyngitis';

-- Node: cad-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Cervical Artery Dissection","body":"**Carotid or vertebral artery dissection** — intimal tear with intramural hematoma causing stenosis/occlusion or pseudoaneurysm.\n\n**Key Context: Strangulation**\n> Non-fatal strangulation is a MAJOR risk factor for cervical artery dissection.\n> Up to 50% of intimate partner violence victims experience strangulation.\n> Symptoms may be delayed 24-72 hours or more.\n\n**Mechanism:** Compression and hyperextension of neck → shearing forces on arteries → intimal tear.\n\n**Mortality:** Strangulation can be fatal with as little as 10 seconds of pressure. [1][2]","citation":[1,2],"next":"cad-mechanism","calculatorLinks":[{"id":"nihss-calculator","label":"NIH Stroke Scale"},{"id":"cervical-artery-dissection","label":"Neck Injury Assessment","kind":"tree","node":"cad-strangulation"}],"summary":"Non-fatal strangulation is a major risk factor — symptoms may delay 24-72 hours"}'::jsonb
WHERE id = 'cad-start' AND tree_id = 'cervical-artery-dissection';

-- Node: code-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Rapid Code Status Conversation","body":"**The \"code status\" conversation is really a goals-of-care conversation** — not just a checklist of procedures to accept or refuse.\n\n**Key Principles:**\n• Focus on what the patient VALUES, not procedures\n• Make a recommendation when appropriate\n• Avoid asking patients to make medical decisions\n• Be honest about prognosis\n• A conversation, not a form to fill out\n\n**Remember:** This is hard. You''re doing something important. [1][2]","citation":[1,2],"next":"code-when","summary":"Code status is a goals-of-care conversation — focus on values, make a recommendation"}'::jsonb
WHERE id = 'code-start' AND tree_id = 'code-status';

-- Node: cfb-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Corneal Foreign Body Removal","body":"> 🚨 **STOP if open globe suspected.** Mechanism + Seidel test FIRST. If you cannot rule out open globe, do not touch the eye except to apply a rigid shield. See [Globe Rupture](#/tree/globe-rupture).\n\n**Scope of this consult:** Removal of superficial corneal or conjunctival foreign body in the ED. Excludes intraocular FB (penetrating), open globe, and central visual axis material requiring ophthalmology.\n\n**Mechanism risk-stratification:**\n- **Low velocity / blunt:** simple grinding, dust, debris under lid — usually superficial\n- **High velocity / metal-on-metal:** grinder without eye protection, hammering metal — assume intraocular FB until proven otherwise; CT orbit usually indicated\n- **Vegetative material:** plant, wood — higher fungal infection risk, lower threshold for ophthalmology referral","citation":[1,2,5,8],"next":"cfb-seidel","summary":"Superficial corneal/conjunctival FB only; rule out open globe with mechanism + Seidel first","skippable":false,"safetyLevel":"critical"}'::jsonb
WHERE id = 'cfb-start' AND tree_id = 'corneal-fb-removal';

-- Node: cfb-eversion (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Eyelid Eversion — Exclude Tarsal FB","body":"**Always evert the upper lid** even if the FB looks corneal. A tarsal FB will be invisible until you flip the lid, and it will keep scratching the cornea with every blink.\n\n**Single eversion (most cases):**\n1. Anesthetize the eye\n2. Ask the patient to look down (NOT close)\n3. Grasp the upper lashes; place a cotton-tip applicator horizontally across the upper lid crease\n4. Roll the lid up and over the cotton-tip — exposes the tarsal conjunctiva\n5. Wipe any FB off the tarsal surface with a moistened cotton-tip\n6. Release; the lid returns to position naturally\n\n**Double eversion** (rarely needed in ED): use a Desmarres retractor or bent paper-clip to expose deeper fornices — typically ophthalmology territory.\n\n**Also check:** lower fornix (pull down lower lid, ask patient to look up).","citation":[2,7,8],"next":"cfb-removal-ladder","summary":"Single eversion with cotton-tip + downward gaze; wipe tarsal FB with moistened cotton-tip"}'::jsonb
WHERE id = 'cfb-eversion' AND tree_id = 'corneal-fb-removal';

-- Node: cfb-removal-ladder (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":4,"title":"Removal Ladder — Start Gentle","body":"**Escalate from least to most invasive.** Most superficial FB come off with irrigation or a cotton-tip; needle removal at the slit lamp is reserved for embedded particles.\n\n**Choose your starting step:**","citation":[2,3,7,8],"options":[{"label":"Loose surface FB or conjunctival sac debris","description":"Try saline irrigation first","next":"cfb-irrigation"},{"label":"FB sitting on cornea, not embedded","description":"Moistened cotton-tip","next":"cfb-cotton-tip"},{"label":"FB embedded in cornea (small, peripheral)","description":"25-27g needle at slit lamp, tangential bevel","next":"cfb-needle"},{"label":"Metallic FB with rust ring","description":"Needle removal + ophthalmic burr for rust","next":"cfb-rust-ring"},{"label":"Central / visual axis / vegetative / multiple","description":"Ophthalmology — do not attempt ED removal","next":"cfb-failure","urgency":"urgent"}],"summary":"Ladder: irrigation → cotton-tip → 25-27g needle at slit lamp → burr for rust ring"}'::jsonb
WHERE id = 'cfb-removal-ladder' AND tree_id = 'corneal-fb-removal';

-- Node: cfb-post-care (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Post-Removal Care","body":"**Recheck visual acuity** — must match or improve compared with pre-procedure.\n\n**Topical antibiotic prophylaxis (3-5 days):**\n• [Erythromycin ointment](#/drug/erythromycin-ointment/corneal-abrasion) qid (cheap, gentle)\n• OR [Polymyxin B–Trimethoprim](#/drug/polymyxin-trimethoprim/corneal-abrasion) 1 drop qid\n• **Contact lens wearers must get Pseudomonas coverage** — [Ciprofloxacin 0.3%](#/drug/ciprofloxacin-ophthalmic/contact-lens-keratitis) or [Moxifloxacin 0.5%](#/drug/moxifloxacin-ophthalmic/contact-lens-keratitis) 1 drop qid x 5-7 days\n• **Vegetative FB** (plant, wood): consider adding antifungal — defer to ophthalmology\n\n**Adjuncts:**\n• Cycloplegic for ciliary spasm pain ([Cyclopentolate 1%](#/drug/cyclopentolate/corneal-abrasion) BID x 1-2 days) — optional, only if significant photophobia\n• **Topical NSAID drops with caution** — limited duration, watch for corneal melt (rare with short courses)\n• **No patching** — Cochrane 2016 found no benefit and possible harm\n• Oral analgesia ([Acetaminophen](#/drug/acetaminophen/general) and/or [Ibuprofen](#/drug/ibuprofen/general))\n\n**Counsel:** No rubbing the eye, no contact lenses until cleared by ophthalmology, return for worsening pain, decreased vision, purulent discharge, or photophobia.","citation":[2,4,6,7],"next":"cfb-followup","summary":"VA recheck, erythromycin/polytrim qid x3-5d, cipro/moxi if contact lens wearer, no patching"}'::jsonb
WHERE id = 'cfb-post-care' AND tree_id = 'corneal-fb-removal';

-- Node: cpr-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Positive Culture Callback — Source Triage","body":"Lab called with a positive culture on a patient previously seen in the ED. Determine source to drive the decision pathway.\n\n**Universal first questions:** [1][2]\n• What is the source?\n• Is the organism a likely pathogen or contaminant?\n• Is the patient symptomatic now?\n• Are they on adequate antibiotic coverage?\n• Special host factors (pregnant, immunocompromised, indwelling device)?\n\n**Select the culture source:**","citation":[1,2],"options":[{"label":"Blood Culture","description":"Bacteremia workup — most time-sensitive","next":"cpr-blood-org","urgency":"critical"},{"label":"Urine Culture (clean catch)","description":"Symptomatic vs asymptomatic bacteriuria","next":"cpr-urine-symptoms"},{"label":"Foley / Indwelling Catheter Urine","description":"CAUTI rules differ from clean catch","next":"cpr-foley-symptoms"},{"label":"Wound Culture","description":"SSTI, abscess, diabetic foot, bite","next":"cpr-wound-context"},{"label":"Sputum Culture","description":"Pneumonia, treatment-failure, structural lung dz","next":"cpr-sputum-context"},{"label":"Stool Culture or C. difficile","description":"Bacterial diarrhea or CDI","next":"cpr-stool-type"},{"label":"CSF Culture","description":"Meningitis — always admit","next":"cpr-csf-admit","urgency":"critical"},{"label":"Throat Culture (GAS)","description":"Strep pharyngitis confirmation","next":"cpr-throat-treat"}],"summary":"Source determines pathway. Always ask: pathogen vs contaminant, symptomatic, on coverage, special host"}'::jsonb
WHERE id = 'cpr-start' AND tree_id = 'culture-positive-results-ed';

-- Node: cpr-blood-org (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Blood Culture — Organism Identified","body":"**Almost always TRUE pathogen (>90%):** [3][4]\nS. aureus, S. pneumoniae, GAS, E. coli, Klebsiella, Pseudomonas, Candida, Listeria, N. meningitidis, Salmonella\n\n**Usually contaminant (<10% unless context):** [3][5]\nCoNS, Corynebacterium, Bacillus, Cutibacterium (P. acnes), Micrococcus, single-bottle viridans strep\n\n**Which organism?**","citation":[3,4,5],"options":[{"label":"S. aureus (MSSA or MRSA)","description":"Never a contaminant — recall + admit + TTE","next":"cpr-sab","urgency":"critical"},{"label":"Candida","description":"Recall + admit + echinocandin + ophtho","next":"cpr-candidemia","urgency":"critical"},{"label":"Gram-negative (E. coli, Klebsiella, etc.)","description":"Pathway driven by coverage + ESBL status","next":"cpr-gnb"},{"label":"Streptococcus (pneumo, GAS, GBS)","description":"Source-directed treatment","next":"cpr-strep-blood"},{"label":"CoNS / likely contaminant","description":"Single-bottle, stable patient, no device","next":"cpr-contam-blood"},{"label":"Other / unfamiliar organism","description":"Pseudomonas, Listeria, anaerobes, etc.","next":"cpr-blood-other"}],"summary":"S. aureus + Candida + GNB sepsis = always recall + admit. CoNS single bottle + stable = likely contaminant."}'::jsonb
WHERE id = 'cpr-blood-org' AND tree_id = 'culture-positive-results-ed';

-- Node: cpr-urine-symptoms (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Urine Culture — Symptomatic Status","body":"**The single most important question for urine culture interpretation.** [15][16]\n\n**Patient status:**","citation":[15,16],"options":[{"label":"Symptomatic (dysuria, frequency, suprapubic pain, fever, flank pain)","description":"Treat UTI by syndrome","next":"cpr-urine-symp"},{"label":"Asymptomatic + pregnant","description":"Must treat ASB in pregnancy","next":"cpr-asb-preg","urgency":"urgent"},{"label":"Asymptomatic + pre-urologic procedure","description":"Treat if mucosal trauma planned","next":"cpr-asb-preop"},{"label":"Asymptomatic + all others","description":"Do NOT treat","next":"cpr-asb-noT"}],"summary":"Symptoms → treat. Asymptomatic → DO NOT treat (exceptions: pregnancy, pre-urologic procedure)."}'::jsonb
WHERE id = 'cpr-urine-symptoms' AND tree_id = 'culture-positive-results-ed';

-- Node: cpr-urine-symp (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Symptomatic UTI — Syndrome","body":"**Cystitis vs pyelonephritis drives both treatment and disposition.** [15]\n\n**Cystitis:** dysuria, frequency, suprapubic discomfort, urinary urgency. No flank pain, no fever.\n\n**Pyelonephritis:** flank pain, fever, rigors, nausea/vomiting, costovertebral angle tenderness.","citation":[15],"options":[{"label":"Uncomplicated Cystitis","description":"Dysuria/frequency only, otherwise well","next":"cpr-cystitis"},{"label":"Pyelonephritis — outpatient candidate","description":"Stable, PO tolerant, reliable follow-up","next":"cpr-pyelo-outpt"},{"label":"Pyelonephritis — admission criteria","description":"Sepsis, vomiting, pregnant, obstruction, fail outpt","next":"cpr-pyelo-admit","urgency":"urgent"}],"summary":"Cystitis → 3-5d PO. Pyelo outpatient → 5-14d. Pyelo admit if sepsis, pregnancy, vomiting, obstruction."}'::jsonb
WHERE id = 'cpr-urine-symp' AND tree_id = 'culture-positive-results-ed';

-- Node: cpr-cystitis (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Uncomplicated Cystitis — Treatment","body":"**First-line (any of):** [15][17]\n• **Nitrofurantoin 100 mg PO BID x 5d** (avoid CrCl <30, avoid in pyelonephritis)\n• **TMP-SMX DS PO BID x 3d** (only if local resistance <20%, no use in 3 months)\n• **Fosfomycin 3g PO x 1 dose** (single dose, lower efficacy, OK for ESBL cystitis only)\n\n**Second-line:** [17]\n• Cephalexin 500 mg PO QID x 5-7d\n• Cefpodoxime 100 mg PO BID x 5-7d\n• Augmentin 500/125 mg PO BID x 5-7d\n\n**Avoid for cystitis:** [17]\n• Fluoroquinolones — FDA 2016 black box, reserve for pyelo\n• Ceftriaxone IV — overkill\n\n**ESBL on culture:** [12]\n• Cystitis only: nitrofurantoin or fosfomycin work\n• Pyelo: ertapenem outpatient or meropenem inpatient","citation":[12,15,17],"next":"cpr-cystitis-action","summary":"Cystitis = nitrofurantoin 5d OR TMP-SMX 3d OR fosfo x1. Avoid FQ for cystitis. ESBL cystitis: nitro/fosfo still work."}'::jsonb
WHERE id = 'cpr-cystitis' AND tree_id = 'culture-positive-results-ed';

-- Node: cpr-wound-context (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":5,"title":"Wound Culture — Context","body":"**Critical principle: surface wound swabs often show colonizers, not pathogens.** [19]\n\n**If patient is improving on empiric therapy + culture shows unexpected organism → continue current therapy.**\n\n**Recall and change ONLY if:** not improving, clearly resistant organism (e.g., MRSA on PCN), unusual pathogen.\n\n**Wound type?**","citation":[19],"options":[{"label":"Cellulitis (non-purulent SSTI)","description":"Strep more likely; surface swabs misleading","next":"cpr-cellulitis"},{"label":"Abscess / purulent SSTI","description":"I&D is primary Rx; MRSA likely","next":"cpr-abscess"},{"label":"Diabetic foot infection","description":"IWGDF/IDSA staging drives Rx","next":"cpr-dfi"},{"label":"Bite wound (animal or human)","description":"Pasteurella + anaerobes mandatory","next":"cpr-bite"}],"summary":"Wound culture: surface swabs often misleading. Continue if improving. Change only if resistant or unusual organism."}'::jsonb
WHERE id = 'cpr-wound-context' AND tree_id = 'culture-positive-results-ed';

-- Node: cpr-stool-type (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":7,"title":"Stool Culture — Pathogen Type","body":"**Bacterial pathogen identification drives treatment decisions:** [24]","citation":[24],"options":[{"label":"Salmonella (non-typhi)","description":"Most patients do NOT need treatment","next":"cpr-salmonella"},{"label":"Shigella","description":"Treat all — high transmission","next":"cpr-shigella"},{"label":"Campylobacter","description":"Treat severe only","next":"cpr-campy"},{"label":"STEC / E. coli O157:H7","description":"DO NOT treat — HUS risk","next":"cpr-stec","urgency":"critical"},{"label":"Vibrio (non-cholera)","description":"Treat sepsis cases, V. vulnificus in cirrhotics","next":"cpr-vibrio"},{"label":"C. difficile","description":"NAAT vs toxin EIA, severity-based Rx","next":"cpr-cdiff"}],"summary":"Stool pathogen: Salmo/Campy = treat only severe. Shigella = treat all. STEC = NEVER treat. CDI = severity-based."}'::jsonb
WHERE id = 'cpr-stool-type' AND tree_id = 'culture-positive-results-ed';

-- Node: cpr-cdiff (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":7,"title":"C. difficile — Interpret Result","body":"**Diagnostic interpretation:** [25]\n• NAAT alone insufficient — can detect colonizers\n• NAAT + toxin EIA positive = true CDI\n• Symptomatic + both positive = treat\n• NAAT positive / toxin negative + asymptomatic = likely colonizer, do NOT treat\n• Patient with NO diarrhea (≥3 unformed stools/24h) — do NOT test or treat\n\n[CDI Severity Calculator](#/node/cpr-cdiff-severity)","citation":[25],"options":[{"label":"CDI confirmed + initial episode","description":"Severity-based Rx","next":"cpr-cdiff-severity"},{"label":"CDI confirmed + recurrence","description":"Adjust Rx, consider FMT consult","next":"cpr-cdiff-recur"},{"label":"NAAT+ / toxin- / asymptomatic","description":"Likely colonizer — do NOT treat","next":"cpr-cdiff-coloniz"}],"summary":"CDI dx: NAAT + toxin both positive OR symptoms + NAAT. NAAT+/toxin-/asymptomatic = colonizer, no Rx."}'::jsonb
WHERE id = 'cpr-cdiff' AND tree_id = 'culture-positive-results-ed';

-- Node: febsz-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Febrile Seizure — Core Frame","body":"[Febrile Seizure Steps Summary](#/info/febsz-steps) · [Disposition, Recurrence & Mimics](#/node/febsz-disposition-complex)\n\n**Most febrile seizures are simple and benign.** [1][2]\n\n**Your job is NOT to \"rule out epilepsy\" — it is to detect dangerous mimics:** [1][4][11]\n• **Bacterial meningitis** (especially under-vaccinated, ill-appearing, persistent AMS)\n• **HSV encephalitis** (focal features, prolonged AMS, focal seizure)\n• **Febrile status epilepticus** (≥30 min or recurrent without recovery)\n• **Electrolyte / glucose derangement**\n• **Non-accidental trauma (NAT)**\n\n**AAP 2011 (reaffirmed 2025) bottom line for SIMPLE febrile seizures:** [1][2][3]\n• **No** routine LP\n• **No** routine labs\n• **No** routine EEG\n• **No** routine neuroimaging\n• **No** anticonvulsant prophylaxis\n• **Antipyretics do NOT prevent recurrence** [3]\n\nReassurance + return precautions for simple cases. Targeted workup for complex / atypical features.","citation":[1,2,3,4,11],"next":"febsz-definition","calculatorLinks":[{"id":"febsz-classifier","label":"Simple vs Complex Classifier"}],"summary":"Job is NOT to rule out epilepsy — detect dangerous mimics (meningitis, HSV, status, NAT); AAP 2011/2025: no routine workup or prophylaxis for simple FS","safetyLevel":"critical"}'::jsonb
WHERE id = 'febsz-start' AND tree_id = 'febrile-seizure';

-- Node: gb-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Biliary Pathology Assessment","body":"**Key Differentials:**\n• **Biliary colic:** Transient cystic duct obstruction, pain <6h, no fever\n• **Acute cholecystitis:** Persistent obstruction + inflammation, pain >6h, fever\n• **Cholangitis:** CBD obstruction + infection (Charcot''s triad)\n• **Choledocholithiasis:** CBD stone ± symptoms\n\n**Initial Assessment:**\n1. History: pain duration, location, fever, jaundice\n2. Physical exam: Murphy''s sign\n3. Labs: CBC, CMP, LFTs, lipase\n\n**What is the primary concern?**\n\n*Basis:* Differential definitions follow the Tokyo Guidelines 2018 diagnostic criteria for acute cholecystitis [2] and acute cholangitis [9], with narrative review context from JAMA 2022 [1]. These are consensus-based diagnostic criteria (expert panel, international multicentre validation), not outcome trials. The 6-hour pain-duration cutoff separating biliary colic from cholecystitis is a conventional clinical teaching threshold, not a validated decision rule.","citation":[1,2,9],"options":[{"label":"RUQ Pain — Need Workup","next":"gb-exam"},{"label":"Known Cholecystitis — Grade Severity","next":"gb-cholecystitis-grade"},{"label":"Suspected Cholangitis (Fever + Jaundice)","next":"gb-cholangitis-assess"}],"summary":"Biliary colic <6h, no fever; cholecystitis >6h + fever; cholangitis = fever + jaundice + RUQ pain"}'::jsonb
WHERE id = 'gb-start' AND tree_id = 'gallbladder';

-- Node: gb-exam (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Physical Exam & Lab Patterns","body":"**Murphy''s Sign:**\n• Technique: Hand on RUQ below costal margin, patient inspires\n• Positive: Inspiratory arrest when hand contacts gallbladder\n• Sensitivity: 75-86%\n• **Specificity: 79-96%** (excellent for ruling IN)\n• **Negative Predictive Value: 90.5%**\n\n**Charcot''s Triad (Cholangitis):**\n• Fever + Jaundice + RUQ pain\n• Present in only 50-70% of cholangitis cases\n• Specificity: 95.9% (if all three present)\n\n**Reynolds'' Pentad (Severe Cholangitis):**\n• Charcot''s triad + Hypotension + Altered mental status\n• Only 4-8% of cholangitis cases\n• Indicates septic shock — emergent drainage needed\n\n**Lab Patterns:**\n\n| Condition | WBC | LFTs | Bilirubin | Lipase |\n|-----------|-----|------|-----------|--------|\n| Biliary colic | Normal | Normal | Normal | Normal |\n| Cholecystitis | ↑ | Normal | Normal | Normal |\n| Cholangitis | ↑ | ↑ ALP | ↑↑ | Normal |\n| Choledocholithiasis | ± | ↑ ALP | ↑ | Normal |\n| Gallstone pancreatitis | ↑ | ↑ | ↑ | ↑↑↑ |\n\n*Basis:* Murphy sign technique and sonographic correlation from Bree [4] and the AFP gallstone review [6]. **Scope limitation — read before relying on these numbers:** the definitive systematic review of the clinical exam in suspected cholecystitis (JAMA Rational Clinical Examination) [15] pooled 17 studies and found the Murphy sign positive likelihood ratio was only 2.8 (95% CI 0.8-8.6, confidence interval crosses 1.0), and concluded that **no single clinical finding or laboratory test is sufficient to establish or exclude acute cholecystitis without imaging**. The specificity range and negative predictive value quoted above come from individual primary studies, not from pooled analysis, and should not be used to rule the diagnosis in or out on their own. Charcot triad specificity derives from the Tokyo Guidelines validation dataset [27], in which the paired reported sensitivity of the triad was 26.4% and specificity 95.6%; the triad frequency figure quoted above comes from older literature and is not the Tokyo-reported value. Reynolds pentad frequency is a descriptive estimate from historical case series with no pooled denominator. Lab-pattern table is a conventional teaching aid [1,2,9], not a validated diagnostic algorithm.","citation":[1,2,3,4,6,9,15,27],"next":"gb-imaging-choice","summary":"Murphy''s sign 79-96% specific; Charcot''s triad 95.9% specific for cholangitis; check LFT pattern"}'::jsonb
WHERE id = 'gb-exam' AND tree_id = 'gallbladder';

-- Node: gb-imaging-choice (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Imaging Selection","body":"**RUQ Ultrasound (First-Line):**\n• Gallstones: Sensitivity >86%, Specificity >88%\n• Overall for cholecystitis: Sens 94%, Spec 84%\n\n**POCUS Findings for Cholecystitis:**\n• Gallstones (echogenic + shadowing)\n• Wall thickening >5mm (90% specific)\n• Pericholecystic fluid\n• Sonographic Murphy''s sign\n\n**When to Get Additional Imaging:**\n\n**CT:** If complications suspected (emphysematous, gangrenous, perforation)\n\n**MRCP:** CBD stones suspected, need to confirm before ERCP\n• Sensitivity 85-100%, Specificity 90%\n\n**HIDA:** Equivocal US, need to confirm cystic duct obstruction\n• 99% specific if gallbladder doesn''t fill\n\n**What do the imaging findings show?**\n\n*Basis:* Ultrasound-first strategy is the Tokyo Guidelines 2018 [2] and WSES 2020 [8] recommendation. **Scope limitation on the accuracy figures above:** the two pooled sources disagree with each other and with the numbers as stated. Shea (meta-analysis, verification-bias adjusted) [17] reported ultrasound for acute cholecystitis at sensitivity 94% / specificity 78% unadjusted and 88% / 80% adjusted, and cholescintigraphy at sensitivity 97% / specificity 90%. Kiewiet (57 studies, 5,859 patients) [16] reported ultrasound sensitivity 81% (95% CI 75-87) and specificity 83% (95% CI 74-89), with cholescintigraphy sensitivity 96% and specificity 90%, and concluded that **the diagnostic accuracy of ultrasound has a substantial margin of error**. Neither pooled source supports a HIDA specificity of 99%. MRCP/EUS performance is from the Cochrane diagnostic test accuracy review [5]. Individual sonographic signs (wall thickening, pericholecystic fluid) have not been validated as standalone criteria; the Tokyo criteria require a combination of local signs, systemic signs, and imaging.","citation":[2,4,5,8,16,17],"options":[{"label":"Gallstones + Positive Sonographic Murphy''s","next":"gb-cholecystitis-grade"},{"label":"Gallstones Only (No Inflammation Signs)","next":"gb-biliary-colic"},{"label":"Dilated CBD (>6mm)","next":"gb-choledocholithiasis"},{"label":"Complications (Gas, Perforation, Abscess)","next":"gb-cholecystitis-severe"}],"summary":"US first-line; POCUS: stones + wall >5mm + sono-Murphy = cholecystitis; MRCP if CBD stone suspected"}'::jsonb
WHERE id = 'gb-imaging-choice' AND tree_id = 'gallbladder';

-- Node: gb-cholecystitis-grade (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Tokyo Guidelines — Cholecystitis Severity","body":"**Grade I (Mild):**\n• Acute cholecystitis without organ dysfunction\n• No severe local inflammation\n• <5% complication rate\n\n**Grade II (Moderate) — ANY of:**\n• WBC >18,000\n• Palpable RUQ mass\n• Symptom duration >72 hours\n• Marked local inflammation:\n  - Gangrenous changes\n  - Pericholecystic abscess\n  - Hepatic abscess\n  - Biliary peritonitis\n  - Emphysematous cholecystitis\n\n**Grade III (Severe) — Organ Dysfunction:**\n• Cardiovascular: vasopressor requirement\n• Neurological: altered mental status\n• Respiratory: PaO2/FiO2 <300\n• Renal: Cr >2.0 or oliguria\n• Hepatic: INR >1.5\n• Hematologic: Platelets <100,000\n\n**What grade?**\n\n*Basis:* Grade I/II/III criteria are reproduced from the Tokyo Guidelines 2018 severity grading for acute cholecystitis [2], endorsed by WSES 2016 [7] and WSES 2020 [8]. This is an international expert-consensus grading system derived from retrospective multicentre cohorts; it stratifies prognosis and guides management intensity but has not been prospectively validated as a treatment-allocation rule in a randomised trial. The organ-dysfunction thresholds (PaO2/FiO2, creatinine, INR, platelets) are the Tokyo definitions and differ from SOFA/qSOFA sepsis criteria — do not use them interchangeably.","citation":[2,7,8],"options":[{"label":"Grade I — Mild","next":"gb-cholecystitis-mild"},{"label":"Grade II — Moderate","next":"gb-cholecystitis-moderate"},{"label":"Grade III — Severe (Organ Dysfunction)","next":"gb-cholecystitis-severe"}],"summary":"Tokyo grading: I = uncomplicated; II = local complications or WBC >18K or >72h; III = organ dysfunction"}'::jsonb
WHERE id = 'gb-cholecystitis-grade' AND tree_id = 'gallbladder';

-- Node: gb-cholangitis-assess (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Cholangitis Assessment","body":"**Tokyo Guidelines 2018 — Diagnostic Criteria:**\n\n**A. Systemic Inflammation:**\n• Fever (>38°C) and/or rigors\n• Elevated WBC (<4K or >10K) or CRP\n\n**B. Cholestasis:**\n• Jaundice (total bili >2)\n• Abnormal LFTs (ALP/GGT elevated)\n\n**C. Imaging:**\n• Biliary dilatation (CBD >6mm, or >10mm post-cholecystectomy)\n• Evidence of etiology (stone, stricture, stent occlusion)\n\n**Diagnosis:**\n• **Definite:** A + B + C all present\n• **Probable:** A + B, or A + C\n\n**Common Causes:**\n• Choledocholithiasis (most common)\n• Stricture (benign or malignant)\n• Stent occlusion\n• Post-ERCP","citation":[2,9],"next":"gb-cholangitis-severity","summary":"Cholangitis diagnosis: systemic inflammation + cholestasis + imaging; definite if all 3 present"}'::jsonb
WHERE id = 'gb-cholangitis-assess' AND tree_id = 'gallbladder';

-- Node: gb-choledocholithiasis (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":5,"title":"Choledocholithiasis Assessment","body":"**Probability Assessment:**\n\n**High Probability (>50%) — ERCP directly:**\n• CBD stone visible on US/CT\n• Clinical cholangitis\n• Bilirubin >4 + dilated CBD (>6mm)\n\n**Intermediate Probability (10-50%) — Get MRCP/EUS:**\n• Dilated CBD (>6mm) without visible stone\n• Bilirubin 1.8-4\n• Abnormal LFTs (elevated ALP, GGT)\n• Age >55\n• Gallstone pancreatitis\n\n**Low Probability (<10%) — Proceed to cholecystectomy:**\n• Normal CBD diameter\n• Normal bilirubin\n• Normal LFTs\n\n**What is the probability?**","citation":[11,12],"options":[{"label":"High Probability — Proceed to ERCP","next":"gb-ercp"},{"label":"Intermediate — Get MRCP","next":"gb-mrcp"},{"label":"Low Probability — Proceed to Chole","next":"gb-surgery-timing"}],"summary":"CBD stone probability: high (visible stone, cholangitis) → ERCP; intermediate → MRCP; low → surgery"}'::jsonb
WHERE id = 'gb-choledocholithiasis' AND tree_id = 'gallbladder';

-- Node: gb-ercp (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"ERCP for Choledocholithiasis","body":"**Indications:**\n• Confirmed CBD stone\n• Clinical cholangitis requiring drainage\n• High probability choledocholithiasis\n\n**Procedure:**\n• Sphincterotomy + balloon/basket extraction\n• >95% stone clearance rate\n\n**Timing:**\n• Cholangitis Grade II-III: within 24h (or emergent)\n• Non-emergent: within 48-72h of diagnosis\n\n**Complications (5-10%):**\n• Post-ERCP pancreatitis (3-5%) — rectal indomethacin reduces risk\n• Bleeding (1-2%)\n• Perforation (0.5-1%)\n• Cholangitis (if incomplete drainage)\n\n**Post-ERCP:**\n• Cholecystectomy if gallbladder stones present\n• Same admission or within 2 weeks\n• Reduces recurrent biliary events (17% → 3%)\n\n**If ERCP Fails:**\n• Percutaneous transhepatic drainage\n• Surgical common bile duct exploration","citation":[10,11,12],"recommendation":"ERCP for CBD stone extraction. >95% success. Cholecystectomy same admission or within 2 weeks.","confidence":"recommended","summary":"ERCP: sphincterotomy + extraction, >95% success; cholecystectomy after to prevent recurrence"}'::jsonb
WHERE id = 'gb-ercp' AND tree_id = 'gallbladder';

-- Node: gb-antibiotics (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Antibiotic Selection Summary","body":"**Cholecystitis:**\n\n| Grade | First-Line | Alternative | Duration |\n|-------|-----------|-------------|----------|\n| I | Pip-tazo 4.5g q6-8h | Amp-sulb 3g q6h | 3-7 days |\n| II | Cefoxitin 2g q6h | CTX + metronidazole | 7-10 days |\n| III | Meropenem 1g q8h | Pip-tazo + aminoglycoside | 7-14 days |\n\n**Cholangitis:**\n\n| Grade | First-Line | Alternative | Duration |\n|-------|-----------|-------------|----------|\n| I | CTX 1-2g q12h + metro | Amp-sulb 3g q6h | 5-7 days |\n| II | Pip-tazo 4.5g q6-8h | Ceftazidime + metro | 7-10 days |\n| III | Meropenem + vanc | Carbapenem + aminoglycoside | 10-14 days |\n\n**Key Organisms:**\n• E. coli (most common)\n• Klebsiella\n• Enterococcus\n• Anaerobes (Bacteroides)\n\n**De-escalation:** Narrow based on cultures when available.","citation":[2,8],"next":"gb-surgery-timing","summary":"Antibiotics by severity; cover gram-negatives + anaerobes; carbapenems for severe; de-escalate on cultures"}'::jsonb
WHERE id = 'gb-antibiotics' AND tree_id = 'gallbladder';

-- Node: gb-surgery-timing (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":7,"title":"Cholecystectomy Timing","body":"**Early Cholecystectomy Evidence (WSES 2020):**\n\n**Within 72 hours (\"Golden 72\"):**\n• Shorter total hospital stay\n• Lower complication rate\n• No increase in surgical difficulty\n• Cost-effective\n\n**Within 24 hours:**\n• Even better outcomes in some studies\n• Same-admission surgery safe if available\n\n**Up to 10 days:**\n• Still safe and feasible\n• No increased operative difficulty vs early\n• Better than delayed (>2 weeks)\n\n**Delayed (>2 weeks) — AVOID if possible:**\n• Higher morbidity (25-30% vs 15-20%)\n• Longer total hospital stay\n• Higher costs\n• Recurrent biliary events\n\n**When is surgery planned?**","citation":[7,8],"options":[{"label":"Early (<72h) — Preferred","next":"gb-disposition-surgery"},{"label":"Delayed (6-8 weeks) — High-Risk Patient","next":"gb-disposition-delayed"},{"label":"Not Surgical Candidate","next":"gb-disposition-nonsurgical"}],"summary":"Early chole (<72h) preferred; even up to 10 days safe; delayed >2 weeks has worse outcomes"}'::jsonb
WHERE id = 'gb-surgery-timing' AND tree_id = 'gallbladder';

-- Node: gifb-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"GI Foreign Body — Object Identification","body":"**Object type determines urgency and management.**\n\n**High-risk objects (emergent/urgent):**\n• **Button batteries** — esophageal = emergent (<2h)\n• **Magnets** — multiple = urgent (can cause fistula)\n• **Sharp objects** — pins, bones, glass\n• **Superabsorbent polymers** — water beads\n\n**Lower-risk objects:**\n• Coins, small blunt objects\n• Small objects <2cm width, <5cm length\n\n**History:**\n• Time of ingestion\n• Object description (size, shape, material)\n• Symptoms: dysphagia, drooling, pain, respiratory distress","citation":[1,2],"options":[{"label":"Button Battery","description":"Disc/coin battery — EMERGENT if esophageal","next":"gifb-button-battery","urgency":"critical"},{"label":"Sharp Object","description":"Pin, needle, bone, glass, razor","next":"gifb-sharp","urgency":"urgent"},{"label":"Multiple Magnets","description":"≥2 magnets or magnet + metal — risk of fistula","next":"gifb-magnets","urgency":"urgent"},{"label":"Blunt Object / Food Bolus","description":"Coin, toy, meat impaction","next":"gifb-blunt"}],"calculatorLinks":[{"id":"gifb-object-risk","label":"Object Risk Classification"}],"summary":"Object type determines urgency: button battery (emergent), sharp/magnets (urgent), blunt (often conservative)","safetyLevel":"warning"}'::jsonb
WHERE id = 'gifb-start' AND tree_id = 'gi-foreign-body';

-- Node: gout-septic-concern (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":3,"title":"Septic Arthritis Concern","body":"**Crystals do NOT exclude concomitant infection.** Gout/CPPD can coexist with septic arthritis. Absence of fever or toxic appearance is not reassuring enough to withhold treatment when infection remains suspected.\n\n**WBC is not a rule-out test:** synovial WBC >50,000/mm3 raises concern but is not diagnostic; lower counts also occur in infection. **78,000/mm3 with crystals is concerning, not reassuring because it is below 85,000.** There is no safe 85,000 cutoff.\n\nRisk factors include immunocompromise, recent joint surgery/injection, injection drug use, skin infection, bacteremia and prosthetic joint. Discuss suspected prosthetic-joint infection urgently with orthopedics before aspiration.\n\n**Persistent clinical concern for septic arthritis, even with crystals:**\n1. Urgent arthrocentesis: synovial culture, Gram stain, WBC/differential and crystals; obtain blood cultures. If stable, collect samples before antibiotics when this can be done promptly.\n2. **Start empiric IV antibiotics when septic arthritis remains suspected. Do not wait for toxic appearance, fever, a positive Gram stain or finalized cultures.** In sepsis/shock, do not delay antibiotics for aspiration. Cover likely organisms including S. aureus; add MRSA/Gram-negative coverage according to risks and local guidance.\n3. **Urgent orthopedic consultation, admission and a joint drainage/source-control plan.** Rheumatology may assist but does not replace orthopedics. Do not substitute outpatient observation or repeat aspiration in 24-48 hours for initial treatment.\n4. Defer gout-directed systemic and intra-articular corticosteroids until infection is reasonably excluded. Sampling alone or a negative Gram stain is not clearance for steroids. Analgesia must not delay infection treatment.\n\n[Septic arthritis: empiric antibiotics](#/tree/septic-arthritis/node/sa-empiric-nongc) · [Full septic arthritis consult](#/tree/septic-arthritis) [11][12]","citation":[6,9,11,12],"recommendation":"Treat persistent concern as suspected septic arthritis: prompt aspiration/cultures, empiric IV antibiotics, urgent orthopedics and admission for drainage planning.","confidence":"recommended","calculatorLinks":[{"id":"gout-vs-septic","label":"Septic Joint Safety Checklist"}],"summary":"Crystals and WBC below 85,000 do not exclude infection: aspirate, give empiric IV antibiotics, consult orthopedics and admit when concern persists","safetyLevel":"critical"}'::jsonb
WHERE id = 'gout-septic-concern' AND tree_id = 'gout';

-- Node: gout-admission-orders (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"Admission Orders","body":"**Persistent clinical concern for septic arthritis, even with crystals:**\n1. Urgent arthrocentesis: synovial culture, Gram stain, WBC/differential and crystals; obtain blood cultures. If stable, collect samples before antibiotics when this can be done promptly.\n2. **Start empiric IV antibiotics when septic arthritis remains suspected. Do not wait for toxic appearance, fever, a positive Gram stain or finalized cultures.** In sepsis/shock, do not delay antibiotics for aspiration. Cover likely organisms including S. aureus; add MRSA/Gram-negative coverage according to risks and local guidance.\n3. **Urgent orthopedic consultation, admission and a joint drainage/source-control plan.** Rheumatology may assist but does not replace orthopedics. Do not substitute outpatient observation or repeat aspiration in 24-48 hours for initial treatment.\n4. Defer gout-directed systemic and intra-articular corticosteroids until infection is reasonably excluded. Sampling alone or a negative Gram stain is not clearance for steroids. Analgesia must not delay infection treatment.\n\n[Septic arthritis: empiric antibiotics](#/tree/septic-arthritis/node/sa-empiric-nongc) · [Full septic arthritis consult](#/tree/septic-arthritis) [11][12]\n\n**Other admission indications when infection is reasonably excluded:** inability to take PO, refractory pain or severe comorbidity. Use appropriate gout therapy only in that separate pathway.\n\n**Before discharge:** reassess for infection, ensure pain control/ambulation, reliable follow-up and an explicit culture-result follow-up plan. A positive crystal result alone does not justify discharge.","citation":[1,11,12],"recommendation":"For suspected septic arthritis: empiric IV antibiotics, urgent orthopedics, admission and source control. Avoid gout steroids while infection remains suspected.","confidence":"recommended","summary":"Admit if septic joint suspected, severe comorbidities, or inability to control pain outpatient"}'::jsonb
WHERE id = 'gout-admission-orders' AND tree_id = 'gout';

-- Node: ht-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Human Trafficking Screening","body":"**Human trafficking occurs in every community** — including yours.\n\n**Definition:** Use of force, fraud, or coercion to exploit a person for labor or commercial sex. For minors, ANY commercial sex is trafficking regardless of force/fraud/coercion.\n\n**Two main types:**\n• **Sex trafficking** — commercial sex acts induced by force, fraud, or coercion\n• **Labor trafficking** — forced labor through similar means\n\n**ED relevance:** 88% of trafficking victims access healthcare while being trafficked, often in EDs. You may be the only person who can help. [4][6][11]","citation":[4,6,11],"next":"ht-who","summary":"ED may be the only healthcare contact for trafficking victims — screen with universal protocol"}'::jsonb
WHERE id = 'ht-start' AND tree_id = 'human-trafficking';

-- Node: hypertensive-emergency-adult-exc-ischemic-stroke (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":3,"title":"Ischemic Stroke: Stroke-Specific BP Rules","body":"**Ischemic stroke** BP rules are stroke-specific and differ before and after thrombolysis. [Stroke consult](#/tree/stroke)\n\n**Do not apply the general first-hour rule** before the thrombolysis decision. [8]\n\n**Before alteplase:** SBP must be below 185 and DBP below 110 mmHg. [10] [Stroke BP threshold before IVT](#/tree/stroke/node/stroke-ivt-check)\n\n**After alteplase:** keep BP below 180/105 mmHg for 24 hours. [10] [Stroke post-treatment BP](#/tree/stroke/node/stroke-post-treatment)","citation":[8,10],"next":"hypertensive-emergency-adult-dispo","recommendation":"Use the stroke consult for BP thresholds: below 185/110 mmHg before thrombolysis and below 180/105 mmHg for 24 hours after. Do not apply the general first-hour rule before the thrombolysis decision.","confidence":"recommended","summary":"Ischemic stroke: stroke consult governs BP, and the thrombolysis decision comes first.","safetyLevel":"critical"}'::jsonb
WHERE id = 'hypertensive-emergency-adult-exc-ischemic-stroke' AND tree_id = 'hypertensive-emergency-adult';

-- Node: hypotension-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Undifferentiated Hypotension — Initial Assessment","body":"**Shock definitions:**\n• **Absolute hypotension:** SBP <90 mmHg or MAP <65 mmHg\n• **Relative hypotension:** SBP drop >40 mmHg from baseline\n• **Shock Index (SI):** HR/SBP — >1.0 suggests significant instability\n\n**Each hour at MAP <65 increases mortality by ~5%.**\n\n**Immediate actions:**\n1. Two large-bore IVs (18G or larger)\n2. Continuous monitoring\n3. ECG immediately\n4. Labs: CBC, CMP, lactate, VBG, troponin, coags\n5. Blood cultures if infection suspected\n6. Type and screen\n7. Foley for UOP monitoring","citation":[1,2],"next":"hypotension-pocus","calculatorLinks":[{"id":"shock-index","label":"Shock Index"},{"id":"map-calculator","label":"MAP Calculator"}],"summary":"MAP <65 or SBP <90; shock index >1 = unstable; each hour at MAP <65 = 5% mortality increase","safetyLevel":"critical"}'::jsonb
WHERE id = 'hypotension-start' AND tree_id = 'hypotension-workup';

-- Node: shock-septic (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Septic Shock — Hour-1 Bundle","body":"**Sepsis-3 definition:** Suspected infection + qSOFA ≥2 or SOFA ≥2.\n**Septic shock:** Sepsis + vasopressors required for MAP ≥65 + lactate >2 despite fluids.\n\n**Hour-1 Bundle (do ALL within 1 hour):**\n\n1. **Measure lactate** — repeat if >2 mmol/L\n2. **Blood cultures** before antibiotics\n3. **Broad-spectrum antibiotics** — each hour delay increases mortality\n4. **30 mL/kg crystalloid** for hypotension or lactate ≥4\n5. **Vasopressors** if hypotensive during/after fluids → MAP ≥65\n\n**Antibiotic selection by source:**\n• Unknown: [Vancomycin](#/drug/vancomycin/sepsis) + [Piperacillin-tazobactam](#/drug/piperacillin-tazobactam/sepsis)\n• Intra-abdominal: Pip-tazo or meropenem + metronidazole\n• Pneumonia: Ceftriaxone + azithromycin or respiratory FQ\n• Urosepsis: Ceftriaxone or FQ","citation":[5,6],"next":"hypotension-vasopressors","treatment":{"firstLine":{"drug":"Crystalloid (LR or NS)","dose":"30 mL/kg","route":"IV","frequency":"Bolus over 3 hours","duration":"Initial resuscitation","notes":"Balanced crystalloid (LR) preferred over NS. Reassess fluid responsiveness frequently."},"alternative":{"drug":"Norepinephrine","dose":"0.01-0.05 mcg/kg/min, titrate to MAP ≥65","route":"IV","frequency":"Continuous","duration":"Until shock resolved","notes":"Start peripherally if needed — do not delay for central line."},"monitoring":"MAP target ≥65 mmHg. Lactate q2-4h. UOP ≥0.5 mL/kg/hr. CRT."},"summary":"Hour-1: lactate, cultures, antibiotics, 30mL/kg crystalloid, vasopressors for MAP ≥65","safetyLevel":"critical"}'::jsonb
WHERE id = 'shock-septic' AND tree_id = 'hypotension-workup';

-- Node: hypotension-fluid-responsiveness (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Fluid Responsiveness Assessment","body":"**Fluid responsiveness ≠ fluid need.** Just because stroke volume will increase doesn''t mean fluids are indicated.\n\n**Passive Leg Raise (PLR) — Most Reliable:**\n• 45° head-up → lower torso to flat + raise legs 45°\n• **>10-15% increase in VTI/CO = fluid responder**\n• Sensitivity 89%, Specificity 91%\n• Works in spontaneous breathing and arrhythmias\n\n**IVC Assessment:**\n• IVC <2 cm + >50% collapse → likely fluid responsive\n• IVC >2 cm + <50% collapse → likely fluid-full\n• **Caveat:** Pooled sens/spec only 71%/75%\n\n**VTI (Velocity-Time Integral):**\n• VTI <18 cm suggests low stroke volume\n• Measure at LVOT, calculate change with PLR\n\n**KEY:** After initial resuscitation, use clinical endpoints (UOP, CRT, lactate) rather than chasing normal IVC/VTI.","citation":[4,12],"next":"hypotension-vasopressors","calculatorLinks":[{"id":"vti-calculator","label":"VTI Calculator"}],"summary":"PLR best (>10-15% VTI increase = responder); IVC collapsibility limited accuracy; fluid responsiveness ≠ need"}'::jsonb
WHERE id = 'hypotension-fluid-responsiveness' AND tree_id = 'hypotension-workup';

-- Node: hypotension-vasopressors (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Vasopressor Selection","body":"**First-line: [Norepinephrine](#/drug/norepinephrine/shock)**\n• Start: 0.01-0.05 mcg/kg/min\n• Titrate: every 2-5 min to MAP ≥65\n• Max: ~0.5-1 mcg/kg/min (consider adding second agent)\n• **Can start peripherally** — do NOT delay for central line\n\n**Second-line options:**\n\n**[Vasopressin](#/drug/vasopressin/shock):**\n• Fixed dose: 0.03-0.04 U/min (no titration)\n• Add when NE >0.25-0.5 mcg/kg/min\n• \"Decatecholaminization\" strategy\n\n**[Epinephrine](#/drug/epinephrine/shock):**\n• 0.01-0.2 mcg/kg/min\n• Low output + bradycardia\n• Causes tachycardia, lactic acidosis at high doses\n\n**[Phenylephrine](#/drug/phenylephrine/shock):**\n• 0.5-1.4 mcg/kg/min\n• Pure alpha — no inotropy\n• Tachycardia with preserved CO","citation":[1,5,13],"next":"hypotension-source-control","treatment":{"firstLine":{"drug":"Norepinephrine","dose":"0.01-0.5 mcg/kg/min","route":"IV","frequency":"Continuous, titrate q2-5 min","duration":"Until shock resolved","notes":"Can start peripherally. Target MAP ≥65 (or 75-85 if chronic HTN)."},"alternative":{"drug":"Vasopressin","dose":"0.03-0.04 U/min fixed","route":"IV","frequency":"Continuous (no titration)","duration":"Until shock resolved","notes":"Add when NE >0.25-0.5 mcg/kg/min. Non-catecholamine vasopressor."},"monitoring":"MAP q5 min until stable. Lactate q2-4h. UOP ≥0.5 mL/kg/hr. CRT."},"calculatorLinks":[{"id":"vasopressor-equivalence","label":"Vasopressor Equivalence"}],"summary":"Norepinephrine first-line; add vasopressin at high NE doses; can start peripherally; target MAP ≥65"}'::jsonb
WHERE id = 'hypotension-vasopressors' AND tree_id = 'hypotension-workup';

-- Node: lefort-type-question (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Le Fort Type","body":"**Select the fracture pattern identified:**","options":[{"label":"Le Fort I (Floating Palate)","description":"Alveolar process separates from upper face","next":"lefort-type1"},{"label":"Le Fort II (Pyramidal)","description":"Entire nasal complex mobile with central incisors","next":"lefort-type2"},{"label":"Le Fort III (Craniofacial Disjunction)","description":"Complete craniofacial separation","next":"lefort-type3","urgency":"critical"},{"label":"Mixed / Bilateral Different","description":"Different levels on each side","next":"lefort-mixed"}],"summary":"Classify Le Fort level: I (floating palate), II (pyramidal), III (craniofacial disjunction)"}'::jsonb
