-- Node: lefort-type1 (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Le Fort I — Horizontal Fracture","body":"**Also called:** Guerin Fracture, Floating Palate [1][2]\n\n**Fracture Line:**\nTransverse through maxilla above tooth roots, crossing:\n• Lateral nasal walls\n• Inferior maxillary sinus walls\n• Pterygoid plates\n\n**Unique Identifier:** Fracture of anterolateral margin of nasal fossa\n\n**Clinical Signs:**\n• Swollen upper lip\n• Anterior open bite malocclusion\n• Ecchymosis of maxillary buccal vestibule and palate\n• Mobile dental arch\n• Epistaxis\n\n**Mechanism:** Downward force applied below the nose","citation":[1,2],"next":"lefort-airway-check","summary":"Le Fort I: transverse maxillary fracture — floating palate, mobile alveolar ridge","skippable":true}'::jsonb
WHERE id = 'lefort-type1' AND tree_id = 'le-fort-fracture';

-- Node: lefort-type2 (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Le Fort II — Pyramidal Fracture","body":"**Also called:** Pyramidal Fracture [1][2][3]\n\n**Fracture Line:**\nPyramid-shaped with base at teeth, apex at nasofrontal suture:\n• Nasal bones\n• Medial orbital walls\n• Orbital floor\n• Infraorbital rims\n• Lateral maxillary walls\n• Pterygoid plates\n\n**Unique Identifier:** Fracture of inferior orbital rim\n\n**Clinical Signs:**\n• Significant facial deformity and swelling\n• Bilateral periorbital edema and ecchymosis (\"raccoon eyes\")\n• Step-off at infraorbital rim (palpable)\n• Infraorbital nerve paresthesia (upper lip, nose)\n• Epistaxis\n• Possible CSF rhinorrhea\n• Diplopia (orbital floor involvement)\n\n⚠️ **Le Fort II is associated with increased mortality** compared to isolated facial fractures.","citation":[1,2,3],"next":"lefort-airway-check","summary":"Le Fort II: pyramidal fracture through nasal bridge and orbital floor — CSF leak risk","safetyLevel":"warning"}'::jsonb
WHERE id = 'lefort-type2' AND tree_id = 'le-fort-fracture';

-- Node: lefort-type3 (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Le Fort III — Craniofacial Disjunction","body":"**Also called:** Floating Face [1][2][3]\n\n**Fracture Line:**\nTransverse through:\n• Nasofrontal suture\n• Medial and lateral orbital walls\n• Zygomaticofrontal suture\n• Zygomatic arches\n• Pterygoid plates\n\n**Unique Identifier:** Zygomatic arch fracture\n\n**Clinical Signs:**\n• Complete craniofacial disjunction\n• \"Dish-face deformity\" — facial elongation and flattening\n• Bilateral periorbital edema and severe ecchymosis\n• Traumatic telecanthus (increased intercanthal distance)\n• Orbital hooding, enophthalmos\n• Mastoid ecchymosis (Battle sign) if basilar skull involved\n• CSF rhinorrhea/otorrhea (highest leak rate)\n• Hemotympanum\n• Anosmia\n• Severe epistaxis\n\n⚠️ **43.5% eventually require tracheostomy**","citation":[1,2,3],"next":"lefort-airway-check","summary":"Le Fort III: craniofacial disjunction — entire face separates from skull, highest CSF leak risk","safetyLevel":"critical"}'::jsonb
WHERE id = 'lefort-type3' AND tree_id = 'le-fort-fracture';

-- Node: lefort-airway-approach (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Intubation Technique","body":"**Positioning:** [4][5]\n• Maintain C-spine precautions (inline stabilization)\n• Slight reverse Trendelenburg if possible (reduces bleeding)\n• Suction IMMEDIATELY available\n\n**Technique:**\n1. Preoxygenation — maximize before attempt\n2. Video laryngoscopy with large-bore suction\n3. Have assistant apply manual reduction of midface if needed\n4. Limit to 1-2 attempts before surgical airway\n\n**Double Setup:**\n✓ Cricothyrotomy kit OPEN on table\n✓ Scalpel in hand of assistant\n✓ Bougie ready\n✓ 6.0 cuffed ETT ready for cric\n\n**RSI Medications:**\n• Ketamine 1-2 mg/kg (maintains respiratory drive if needed for awake)\n• Rocuronium 1.2 mg/kg (full dose for rapid onset)\n• Avoid succinylcholine if concern for hyperkalemia (crush injury)","citation":[4,5],"next":"lefort-hemorrhage-check","summary":"If oral intubation fails: surgical airway — avoid nasotracheal, avoid blind nasal passage in all Le Forts","safetyLevel":"critical"}'::jsonb
WHERE id = 'lefort-airway-approach' AND tree_id = 'le-fort-fracture';

-- Node: lefort-hemorrhage-control (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Hemorrhage Control — Stepwise","body":"**Stepwise Approach:** [6][7]\n\n**1. Direct Pressure & Hemostatic Sutures**\n• Control lacerations\n• Pack oral cavity if needed\n\n**2. Anterior Nasal Packing**\n• Gauze soaked in 1:10,000 epinephrine\n• Commercial devices (Rapid Rhino, Merocel)\n• Can leave up to 48 hours\n\n**3. Posterior Nasal Packing / Balloon Tamponade**\n• Foley catheter: Insert through nose, inflate balloon (10-15 mL) in nasopharynx, apply anterior traction and secure\n• Double-balloon catheters: 70% success rate\n• Overall success: 48-83%\n• ⚠️ **Caution:** Risk of malposition intracranially if skull base fractured\n• **Requires:** Admission, telemetry (nasal-cardiac reflex), sometimes intubation","citation":[6,7],"next":"lefort-hemorrhage-refractory","summary":"Anterior + posterior nasal packing — Foley catheter inflated in nasopharynx for posterior bleeding"}'::jsonb
WHERE id = 'lefort-hemorrhage-control' AND tree_id = 'le-fort-fracture';

-- Node: lefort-imaging (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Imaging Protocol","body":"**CT Face (Gold Standard):** [2][8]\n• Fine-cut CT (2-3mm slices)\n• Axial, coronal, and sagittal planes\n• Both bone and soft tissue windows\n\n**Key Findings to Identify:**\n• Pterygoid plate fractures (mandatory for diagnosis)\n• Anterolateral nasal fossa (Le Fort I)\n• Inferior orbital rim (Le Fort II)\n• Zygomatic arch (Le Fort III)\n\n**3D Reconstruction:**\n• Best method for classifying Le Fort fractures\n• Essential for surgical planning\n• Helps communicate injury extent\n\n**Additional Required Imaging:**\n• **CT Head:** Required — 40.7% have skull fractures, 5.4% TBI\n• **CT C-spine:** Required — maintain immobilization until cleared\n• **CT Angiography:** Consider if penetrating trauma or suspicion of major vascular injury","citation":[2,8],"next":"lefort-ocular","summary":"CT face with 3D reconstruction — defines fracture pattern for surgical planning"}'::jsonb
WHERE id = 'lefort-imaging' AND tree_id = 'le-fort-fracture';

-- Node: lgib-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Lower GI Bleed — Initial Assessment","body":"**Lower GI bleeding** originates distal to the ligament of Treitz. Presents as hematochezia (bright red blood per rectum), maroon stool, or melena (if slow transit).\n\n**First priority:** Assess hemodynamic status.\n\n• HR, BP, orthostatic vitals\n• Shock Index (HR/SBP) — >1.0 suggests significant bleeding\n• Mental status, skin perfusion\n• Signs of hypovolemic shock\n\n**CRITICAL:** Up to 15% of apparent LGIB is actually brisk UGIB. Consider NGT aspirate or EGD if hemodynamically unstable with unclear source.","citation":[1,2],"options":[{"label":"Hemodynamically Unstable","description":"SBP <90, HR >100, shock index >1, altered mental status","next":"lgib-unstable","urgency":"critical"},{"label":"Hemodynamically Stable","description":"Normal vitals, no signs of shock","next":"lgib-stable-risk"}],"calculatorLinks":[{"id":"shock-index","label":"Shock Index"},{"id":"oakland-score","label":"Oakland Score"}],"summary":"Assess hemodynamics first; shock index >1 = significant bleed; 15% of apparent LGIB is brisk UGIB","safetyLevel":"critical"}'::jsonb
WHERE id = 'lgib-start' AND tree_id = 'lower-gi-bleed';

-- Node: lgib-resuscitation (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Resuscitation & Transfusion","body":"**IV Fluid Resuscitation:**\n• Balanced crystalloid (LR preferred over NS)\n• Avoid over-resuscitation — may worsen bleeding\n• Target MAP ≥65 mmHg\n\n**Transfusion Thresholds:**\n• **Hgb <7 g/dL** — transfuse in stable patients\n• **Hgb <8 g/dL** — transfuse if cardiovascular disease or symptomatic\n• **Active hemorrhage** — transfuse regardless of Hgb\n\n**Massive Transfusion Protocol:**\n• Activate if shock index >1.0 + ongoing bleeding\n• Target 1:1:1 ratio (pRBC:FFP:platelets)\n• Do NOT give tranexamic acid (TXA): the ACG 2023 guideline recommends against antifibrinolytics in LGIB after the HALT-IT trial showed no mortality benefit and increased venous thromboembolism\n\n**Coagulopathy Correction:**\n• Platelets if <30k (target >50k before endoscopy) with active bleeding\n• FFP if INR >2.5 and unstable despite resuscitation; endoscopy is generally safe at INR ≤2.5\n• Fibrinogen replacement if <150 mg/dL\n• Avoid routine anticoagulation reversal unless hemodynamically unstable despite resuscitation","citation":[1,3,5],"next":"lgib-imaging","treatment":{"firstLine":{"drug":"Packed Red Blood Cells","dose":"1-2 units","route":"IV","frequency":"As needed","duration":"Until Hgb target reached","notes":"Threshold: <7 g/dL stable, <8 g/dL cardiac disease, any Hgb if active hemorrhage"},"alternative":{"drug":"Platelet transfusion","dose":"Target platelets >50k before endoscopy","route":"IV","frequency":"As needed for active bleeding","duration":"Until target reached","notes":"Transfuse for platelets <30k with active bleeding; do NOT use TXA (ACG 2023 recommends against antifibrinolytics; HALT-IT showed no benefit and increased VTE)"},"monitoring":"Serial Hgb q4-6h during active bleeding; coagulation studies; hemodynamics"},"summary":"Transfuse Hgb <7 (stable) or <8 (cardiac); MTP if shock + ongoing bleeding; do NOT give TXA (ACG recommends against)","safetyLevel":"warning"}'::jsonb
WHERE id = 'lgib-resuscitation' AND tree_id = 'lower-gi-bleed';

-- Node: lp-paramedian-steps (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Paramedian LP — Step-by-Step Guide","body":"[Why & When — Paramedian Overview](#/node/lp-paramedian-start) | [Insertion Detail & Troubleshooting](#/node/lp-paramedian-insertion)\n\n**Three steps, based on Dr. Hadzic''s paramedian technique.** [12]\n\n---\n\n**STEP 1 — LOCATE THE L5-S1 INTERSPACE**\n• **Palpate the iliac crests** — the line connecting them typically crosses at L4-L5\n• **Target L5-S1** (just caudal) — often the largest, most accessible interspace, especially in older patients with calcified upper interspaces\n\n---\n\n**STEP 2 — MARK THE ENTRY POINT**\nFrom the center of L5-S1 interspace:\n• **2 cm lateral** to midline\n• **2 cm caudal** from interspace\n• Bypasses calcified midline ligaments\n\n---\n\n**STEP 3 — TRAJECTORY & CONFIRM**\n• **Angle 30-45° cephalad and toward midline**\n• **Tactile feel:** Soft tissue only — no ligament resistance until dura\n• Confirm loss of resistance at ligamentum flavum, then dural pop → CSF","citation":[12],"next":"lp-paramedian-insertion","images":[{"src":"images/lumbar-puncture/lp-paramedian-step1-locate.jpg","alt":"Step 1 — Locate the L5-S1 interspace by palpating iliac crests","caption":"Step 1: Locate the L5-S1 interspace. Iliac crest line crosses at L4-L5; target one level caudal at L5-S1."},{"src":"images/lumbar-puncture/lp-paramedian-step2-entry.jpg","alt":"Step 2 — Mark entry point 2 cm lateral and 2 cm caudal from L5-S1","caption":"Step 2: Mark entry point — 2 cm lateral to midline, 2 cm caudal from the interspace center."},{"src":"images/lumbar-puncture/lp-paramedian-step3-trajectory.jpg","alt":"Step 3 — Trajectory 30-45 degrees cephalad and toward midline","caption":"Step 3: Trajectory 30-45° cephalad and toward midline. Soft tissue only until dura — no ligamentous resistance. Based on Dr. Hadzic''s paramedian technique."}],"summary":"Paramedian 3-step: locate L5-S1 → mark 2cm lateral + 2cm caudal → angle 30-45° cephalad/medial","skippable":true}'::jsonb
WHERE id = 'lp-paramedian-steps' AND tree_id = 'lumbar-puncture';

-- Node: mcp-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Psych Medical Stability","body":"**Use \"medical assessment/stability,\" not a blanket clearance mindset.**\n\n**Why this matters:**\n• Medical mimics are uncommon in low-risk known psychiatric presentations, but high-impact when red flags are present\n• Missed medical diagnoses in psychiatric patients are reported across a wide range because risk depends heavily on age, vitals, exam, delirium, intoxication, and baseline history\n• Psychiatric patients have higher rates of comorbid medical illness\n\n**AAEP Task Force 2017:**\nMedical evaluation is based on clinical assessment, not routine testing.","citation":[1,2],"next":"mcp-vitals","summary":"Psych medical assessment: history, vitals, exam, mentation, and red flags drive testing; routine labs are not automatic."}'::jsonb
WHERE id = 'mcp-start' AND tree_id = 'medical-clearance-psych';

-- Node: nms-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Neuroleptic Malignant Syndrome","body":"**Definition:** Life-threatening reaction to dopamine antagonists (antipsychotics).\n\n**Classic tetrad:**\n* **Hyperthermia** (often >40 degC)\n* **Lead-pipe rigidity** (severe, generalized)\n* **Autonomic instability** (tachycardia, labile BP, diaphoresis)\n* **Mental status changes** (confusion -> coma)\n\n**Onset:** Usually within 2 weeks of drug initiation/dose change (often 4-14 days)","citation":[1],"next":"nms-triggers","summary":"NMS = hyperthermia + lead-pipe rigidity + autonomic instability + AMS. Onset 4-14 days."}'::jsonb
WHERE id = 'nms-start' AND tree_id = 'nms';

-- Node: oct-exam-rules (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Ocular Trauma — Exam Rules","body":"**If open globe suspected (any of: peaked/teardrop pupil, full-thickness laceration, prolapsed uvea, hyphema with poor view, sudden severe pain + vision loss):**\n• ❌ NO tonometry\n• ❌ NO lid retraction (use desmarres or just gentle lateral lift)\n• ❌ NO eye drops (cycloplegics, mydriatics, antibiotics — wait for OR)\n• ❌ NO seidel test (the dye costs nothing but pressure on globe does)\n• ❌ NO ultrasound (extrinsic pressure can extrude contents)\n• ✅ Rigid Fox shield (NOT pressure patch)\n• ✅ NPO\n• ✅ IV vancomycin + ceftazidime (prophylaxis vs Bacillus, gram-negatives)\n• ✅ Antiemetics (vomiting → Valsalva → extrusion)\n• ✅ CT orbits without contrast (1 mm cuts) — looking for IOFB, globe shape\n• ✅ Ophthalmology to OR\n\n**If open globe NOT suspected:**\n• Slit lamp with fluorescein (Seidel test, abrasion mapping)\n• Tonometry (Tono-Pen or iCare) — defer if any doubt\n• Dilated fundus exam (or call ophtho if you don''t have skills)\n• Lid eversion if FB sensation persists\n\n**Image references:**\n• Open globe with peaked pupil\n• Seidel test positive [1][5]","citation":[1,5],"options":[{"label":"Return to triage","next":"oct-start"}]}'::jsonb
WHERE id = 'oct-exam-rules' AND tree_id = 'ocular-trauma';

-- Node: oct-peds-considerations (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Pediatric Ocular Trauma — Special Rules","body":"**Children are not small adults in ocular trauma.** Three patterns to know:\n\n**1. White-Eyed Blowout Fracture (WEBOF)** — pediatric-specific\n• Trapdoor inferior orbital wall fracture with muscle entrapment\n• External eye looks normal (no bruise, no proptosis) → \"white-eyed\"\n• Triad: persistent N/V + bradycardia (oculocardiac reflex) + restricted up-gaze\n• Surgical emergency — 24-48 hr or muscle ischemia\n• CT thin-cuts orbits without contrast — look for entrapped tissue, not just fracture line [7][8]\n\n**2. Abusive Head Trauma (AHT) Eye Findings**\n• Multilayered, multiquadrant retinal hemorrhages out to ora serrata\n• Without external trauma signs to explain\n• Mandatory ophthalmology dilated exam + child protection consult\n• Peds AHT retinal hemorrhages reference [9]\n\n**3. Cooperation challenges**\n• Distraction, gentle papoose, parent-on-lap exam\n• Topical anesthetic single-use for exam only\n• Sedation only with anesthesia + ophtho support — NOT PO sedation in unstable airway\n• If exam impossible and concern persists → exam under anesthesia with ophthalmology\n\n**4. Other peds patterns:**\n• Toy projectiles (bow/arrow, BB, paintball) → high IOFB rate\n• Bungee cord → high open globe rate\n• Always ask about timing, mechanism, witnesses, eye protection","citation":[7,8,9],"options":[{"label":"WEBOF suspected (entrapment, peds)","next":"oct-peds-webof","urgency":"critical"},{"label":"AHT concern (retinal hemorrhages)","next":"oct-peds-aht"},{"label":"Standard peds eval — return to triage","next":"oct-start"}]}'::jsonb
WHERE id = 'oct-peds-considerations' AND tree_id = 'ocular-trauma';

-- Node: oct-chemical-irrigate (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":3,"title":"Chemical Burn — IRRIGATE AT TRIAGE","body":"**Irrigation comes FIRST. Before VA. Before history. Before exam.** Time-to-irrigation is the most important predictor of outcome.\n\n**Protocol:**\n1. Topical anesthetic (proparacaine) — single drop, allows tolerance of irrigation\n2. Place Morgan lens (or wide-bore IV tubing) — both eyes if bilateral\n3. **Irrigate with 1-2 L LR or NS minimum** (alkali burns may need 4-6 L+)\n4. Sweep upper and lower fornices to remove particulate (cement, lime)\n5. Continue until **pH 7.0-7.4 sustained for 5 min after irrigation stopped**\n6. Recheck pH at 5 and 30 min off irrigation — alkali rebounds\n\n**Alkali (lye, ammonia, drain cleaner, cement, fertilizer) > acid:**\n• Alkali penetrates deep — saponifies cell membranes, tracks into AC, damages limbal stem cells, intraocular structures, can perforate\n• Acid coagulates proteins → barrier (less deep penetration) — except hydrofluoric acid which acts like alkali\n\n**After irrigation complete:**\n• Document VA\n• Slit lamp with fluorescein — assess corneal epithelial defect, **limbal ischemia (white \"porcelain\" limbus)** — most important prognostic finding\n• Evert lids to check for retained particulate\n• Stage with Roper-Hall or Dua [calculator](#/calculator/roper-hall-dua)\n\n[Chemical Burn Irrigation Protocol overlay](#/info/oct-chemical-irrigation) [13][14]","citation":[13,14],"options":[{"label":"Irrigation done — stage severity","next":"oct-chemical-staging"}],"recommendation":"**Chemical burn: irrigate AT TRIAGE before exam. 1-2 L minimum, pH 7.0-7.4 sustained x5min off. Alkali = worse. Stage with Roper-Hall/Dua.**","confidence":"definitive","summary":"Chemical burn: IRRIGATE FIRST. 1-2 L until pH 7.0-7.4 sustained. Limbal ischemia = prognostic.","safetyLevel":"critical"}'::jsonb
WHERE id = 'oct-chemical-irrigate' AND tree_id = 'ocular-trauma';

-- Node: oct-hyphema-mgmt (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Hyphema — Management","body":"**Grade with [hyphema calculator](#/calculator/hyphema-calc):**\n• Microhyphema: only RBCs in AC, no layered blood\n• Grade I: <1/3 AC layered\n• Grade II: 1/3-1/2 AC layered\n• Grade III: >1/2 but not full\n• Grade IV: full AC (\"eight-ball\" hyphema) — worst prognosis\n\n**Critical: SICKLE SCREEN every Black, Mediterranean, Middle Eastern, Indian patient.**\n• Sickled RBCs in AC are stiff → trabecular meshwork blockade → IOP spike\n• ❌ **AVOID acetazolamide, methazolamide, dorzolamide** — acidify AC, worsen sickling\n• ❌ **AVOID mannitol** — same risk\n• Use timolol, brimonidine, prostaglandin analogs for IOP control\n• Surgical AC washout threshold is lower in sickle pts (IOP >24 ×24h vs >50 ×5d in non-sickle)\n\n**Standard management (non-sickle):**\n• Bedrest with HOB 30-45° (lets blood layer inferior, clears visual axis)\n• Eye shield (rigid Fox)\n• Topical cycloplegic (atropine 1% BID — comfort, reduces re-bleed risk)\n• Topical steroid (prednisolone acetate 1% q2-4h — reduces inflammation, may reduce re-bleed)\n• Tranexamic acid PO 25 mg/kg TID **or** aminocaproic acid (Amicar) PO 50 mg/kg q4h x 5 days — reduces re-bleed (~30% incidence on day 2-5)\n• Avoid aspirin/NSAIDs (re-bleed risk)\n• Daily ophthalmology follow-up\n• IOP monitoring: target <24 mmHg (non-sickle), <20 (sickle)\n\n**Re-bleed risk highest day 2-5; eight-ball + sickle = high-risk for OR washout.** [17][18]","citation":[17,18],"recommendation":"**Hyphema: sickle screen at-risk pts. Bedrest 30°, shield, atropine, pred, antifibrinolytic. NO ASA/NSAID. NO CAI/mannitol if sickle. Daily ophtho.**","confidence":"definitive","summary":"Hyphema: sickle screen, bedrest 30°, shield, atropine, pred, antifibrinolytic. NO CAI/mannitol if sickle. Re-bleed d2-5.","safetyLevel":"warning"}'::jsonb
WHERE id = 'oct-hyphema-mgmt' AND tree_id = 'ocular-trauma';

-- Node: oct-ocs-cantholysis (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Orbital Compartment Syndrome — Lateral Canthotomy + Cantholysis NOW","body":"**Vision-loss window: 90-120 minutes from onset of optic nerve ischemia. Do NOT wait for CT, ophthalmology, or transfer. This is a bedside ED procedure.**\n\n**Diagnosis (any 2 of):**\n• Proptosis (most reliable physical finding)\n• IOP >40 mmHg\n• Vision loss / RAPD\n• Resistance to retropulsion\n• Severe orbital pain\n• Limited or absent EOM\n\n**Common causes:** retrobulbar hemorrhage post-trauma, orbital cellulitis with abscess, post-op, anticoagulation + minor trauma, thyroid eye disease decompensation.\n\n**4-step canthotomy + cantholysis:**\n1. **Anesthetize** — 1-2% lidocaine with epi injected SC into lateral canthus (or do the cantholysis dry if catastrophic)\n2. **Hemostat crush** — clamp lateral canthus horizontally for 60-90 sec to crush tissue, reduce bleeding\n3. **Canthotomy** — straight scissors, horizontal cut from lateral canthus to orbital rim (~1-1.5 cm)\n4. **Inferior cantholysis** — pull lower lid laterally + away from globe, palpate the inferior crus of the lateral canthal tendon (taut band), strum-and-cut. **Tendon release is the actual decompression — canthotomy alone is inadequate.** Add superior cantholysis if IOP not relieved.\n\n**Check IOP after cantholysis** — should drop to <30. If not, repeat / extend cantholysis or perform lateral orbital decompression (rare ED skill).\n\n**After:**\n• Topical antibiotic ointment to wound\n• Ophthalmology / oculoplastics urgent consult\n• Ice to forehead (reduces bleeding/swelling)\n• Reverse anticoagulation if applicable\n• CT orbits to confirm cause/check for posterior bleed\n\n[Cantholysis Decision overlay](#/info/oct-cantholysis) [19][20]","citation":[19,20],"recommendation":"**OCS: 4-step lateral canthotomy + INFERIOR CANTHOLYSIS at bedside NOW. Do NOT wait for CT, ophtho, or transfer. Tendon cut = actual decompression. 90-120 min window.**","confidence":"definitive","summary":"OCS: canthotomy + cantholysis NOW (90-120 min). Tendon cut = decompression. No waiting on CT/ophtho.","safetyLevel":"critical"}'::jsonb
WHERE id = 'oct-ocs-cantholysis' AND tree_id = 'ocular-trauma';

-- Node: oct-orbital-fx (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Orbital Wall Fracture","body":"**CT orbits without contrast (1 mm coronal + axial cuts) is gold standard.**\n\n**Common patterns:**\n• Inferior wall (orbital floor) — most common, \"blowout\"\n• Medial wall (lamina papyracea) — paper-thin\n• Combined floor + medial\n\n**ED management:**\n• Document VA, EOM, infraorbital sensation (V2 distribution)\n• Check for entrapment (restricted up-gaze + N/V + bradycardia = WEBOF in peds)\n• Check for retrobulbar hemorrhage on CT (any proptosis on imaging)\n• Nasal precautions: NO nose blowing, no straining (orbital emphysema risk through ethmoid)\n• Antibiotic: amoxicillin-clavulanate 875 mg PO BID x 7-10 days for sinus communication (controversial, some institutions don''t — follow your ophtho/ENT preference)\n• Ice + HOB 30°\n• Decongestant (oxymetazoline) for nasal congestion\n• Oculoplastics or ENT outpatient follow-up 7-10 days for fracture repair decision\n\n**Surgical indications (typically):**\n• Entrapment with positive forced duction\n• Persistent diplopia in primary or down-gaze >2 weeks\n• Cosmetic enophthalmos\n• Large fracture (>50% floor) at risk of late enophthalmos\n• WEBOF in peds (within 24-48 hr)\n\nOrbital blowout CT reference [21]","citation":[21],"recommendation":"**Orbital fx: CT 1mm coronal+axial. Check entrapment, V2, retrobulbar hemorrhage. Nasal precautions, ice, HOB 30°. Oculoplastics/ENT 7-10d. Peds entrapment = 24-48h.**","confidence":"recommended","summary":"Orbital fx: CT 1mm. Check entrapment+V2. Nasal precautions. Outpatient oculoplastics 7-10d. Peds entrapment = urgent."}'::jsonb
WHERE id = 'oct-orbital-fx' AND tree_id = 'ocular-trauma';

-- Node: oct-peds-aht (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Pediatric AHT — Eye Findings","body":"**Multilayered, multiquadrant retinal hemorrhages extending to ora serrata** in a child without a credible accidental mechanism = abusive head trauma until proven otherwise.\n\n**Classic findings:**\n• Bilateral retinal hemorrhages (preretinal, intraretinal, subretinal — multilayered)\n• Extending to ora serrata (peripheral retina) — distinguishes AHT from accidental\n• Macular schisis (traumatic retinoschisis) — highly specific for shaking\n• Vitreous hemorrhage (severe)\n• Optic nerve sheath hemorrhage on imaging\n\n**Workup:**\n• Mandatory dilated fundus exam by ophthalmology (peds preferred) — RetCam if available\n• CT/MRI brain (subdural, parenchymal injury)\n• Skeletal survey if <2 yo\n• Coagulation studies\n• Consult Child Protection Team / SCAN team / DCFS per institution\n• Document all findings carefully — medicolegal\n\nAHT retinal hemorrhage reference [9]","citation":[9],"recommendation":"**Peds AHT eye: multilayered/multiquadrant retinal heme to ora serrata. Mandatory ophtho dilated exam, CT/MRI brain, skeletal survey, child protection.**","confidence":"definitive","summary":"Peds AHT: multilayered retinal heme to ora serrata. Ophtho dilated exam + brain imaging + child protection.","safetyLevel":"critical"}'::jsonb
WHERE id = 'oct-peds-aht' AND tree_id = 'ocular-trauma';

-- Node: oct-subconj-hemorrhage (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Subconjunctival Hemorrhage","body":"**Bright red blood under conjunctiva** — looks dramatic, usually benign in isolation.\n\n**Reassuring features:**\n• Painless\n• Normal VA\n• Sectorial (not 360°)\n• Sclera visible posteriorly\n• No history of high-velocity trauma\n\n**Concerning features (rule out occult open globe):**\n• 360° hemorrhage with chemosis\n• Bullous appearance\n• Pain out of proportion\n• Decreased VA\n• High-velocity mechanism (BB, grinding metal)\n• Inability to see posterior extent on exam\n\n**If concerning:** treat as open globe pathway with shield + CT.\n\n**If benign:**\n• Reassurance — resolves over 1-2 weeks (yellow → green → gone)\n• Artificial tears for comfort\n• Rule out HTN, anticoagulation issue, recurrent episodes (work-up if recurrent)\n• Return precautions: vision change, severe pain, photophobia","citation":[1],"recommendation":"**Isolated SCH: reassurance + tears, resolves 1-2 wk. 360°/chemosis/painful = treat as open globe pathway.**","confidence":"definitive","summary":"Isolated SCH: reassurance, tears. 360°+chemosis+pain = open globe r/o."}'::jsonb
WHERE id = 'oct-subconj-hemorrhage' AND tree_id = 'ocular-trauma';

-- Node: onc-ici-recognize (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":11,"title":"ICI Toxicity (irAE) — Recognition","body":"[Full ICI Toxicity Algorithm](#/info/ici-toxicity-algorithm)\n\n**Drug class:** PD-1 (pembrolizumab, nivolumab, cemiplimab, dostarlimab), PD-L1 (atezolizumab, durvalumab, avelumab), CTLA-4 (ipilimumab, tremelimumab), LAG-3 (relatlimab). Combinations (ipi/nivo) carry 2-3× the irAE rate of monotherapy. [28][29]\n\n**Critical:** irAEs can occur weeks to MONTHS after the last dose. Always ask about ICI exposure in the past 6-12 months.\n\n**Onset by organ:**\n| irAE | Typical Onset |\n|------|--------------|\n| Skin (rash, pruritus) | 2-3 weeks |\n| Colitis | 5-10 weeks |\n| Hepatitis | 8-12 weeks |\n| Pneumonitis | 9-12 weeks |\n| Endocrinopathy | 7-20 weeks |\n| Renal (AIN) | 12-15 weeks |\n| Myocarditis | Variable; can be fulminant within first 2 cycles |\n\n**Universal CTCAE principles:**\n• Grade 1: continue ICI, supportive care\n• Grade 2: hold ICI, oral [prednisone](#/drug/prednisone/irae) 0.5-1 mg/kg/day\n• Grade 3: hold ICI, IV [methylprednisolone](#/drug/methylprednisolone/irae) 1-2 mg/kg/day, infliximab/MMF if no response in 48-72h\n• Grade 4: discontinue permanently, ICU, IV steroids 2 mg/kg/day + biologic\n\n**Steroid taper:** at least 4-6 weeks once Grade ≤1. Add **PJP prophylaxis ([sulfamethoxazole-trimethoprim](#/drug/tmp-smx/pjp-prophylaxis-steroids))** if steroids ≥20 mg prednisone-equivalent for >4 weeks.\n\nWhich organ system is involved?","citation":[28,29,30],"options":[{"label":"Pneumonitis (dyspnea, cough, hypoxia, GGOs on CT)","next":"onc-ici-pneumonitis","urgency":"critical"},{"label":"Colitis (≥3 stools/day above baseline, abd pain, blood)","next":"onc-ici-colitis","urgency":"critical"},{"label":"Hepatitis (LFT elevation)","next":"onc-ici-hepatitis"},{"label":"Endocrine (adrenal crisis, hypophysitis, thyroid, T1DM)","next":"onc-ici-endocrine","urgency":"critical"},{"label":"Myocarditis (chest pain, dyspnea, troponin↑, arrhythmia)","next":"onc-ici-myocarditis","urgency":"critical"},{"label":"Other (renal, neuro, derm, heme)","next":"onc-ici-other"}],"summary":"ICI irAEs occur weeks-months post-dose; G1 cont, G2 hold + PO pred, G3 IV methylpred + infliximab if refractory, G4 d/c + ICU"}'::jsonb
WHERE id = 'onc-ici-recognize' AND tree_id = 'oncological-emergencies';

-- Node: on-confirm (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Optic Neuritis - Confirm the Diagnosis","body":"**Classic ON features:**\n- Subacute monocular vision loss over hours to days (rarely bilateral simultaneous in adults)\n- **Pain with eye movement** (>90% of typical MS-ON) - the single most useful symptom\n- **Color desaturation** disproportionate to visual acuity (red looks washed-out, brown, or grey)\n- **RAPD** on the affected side (if bilateral and symmetric, RAPD may be absent)\n- **Central scotoma** on confrontation or formal fields\n- Disc exam: **two-thirds retrobulbar (normal disc), one-third papillitis (swollen disc)** - normal disc does NOT rule out ON\n\n**Atypical features that should raise suspicion for non-MS etiology** (NMOSD, MOG-AD, sarcoid, syphilis, paraneoplastic):\n- Bilateral simultaneous loss\n- No light perception\n- No recovery at 4-6 weeks\n- Severe disc swelling with hemorrhages\n- Macular star (neuroretinitis - think cat scratch / Bartonella)\n- Age <12 or >50\n- Steroid-dependent / steroid-non-responsive\n\nIf any atypical feature: send the full antibody panel and image the spine.\n\n**Basis for the above:** The symptom frequencies and the two-thirds retrobulbar / one-third papillitis split are drawn from the Optic Neuritis Treatment Trial baseline cohort [1]. The atypical red-flag list follows the Lancet Neurology optic neuritis review [2], AAO BCSC Section 5 [5], and the proposed acute optic neuritis investigation protocol [13]. Each reference is listed in full with PMID/ISBN so the underlying data can be independently reviewed.","citation":[1,2,5,13],"next":"on-subtype","summary":"Pain with eye movement + color desat + RAPD + central scotoma. Normal disc does NOT rule out ON.","safetyLevel":"critical"}'::jsonb
WHERE id = 'on-confirm' AND tree_id = 'optic-neuritis';

-- Node: on-hub-gca (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"GCA / Arteritic AION","body":"**Next 5 minutes:**\n- **Methylprednisolone 1 g IV NOW** - do NOT wait for biopsy, do NOT wait for ESR/CRP if clinical suspicion is high\n- Send ESR, CRP, CBC (thrombocytosis common), platelets, BMP\n- Temporal artery biopsy scheduled within 1-2 weeks (steroid does NOT invalidate biopsy in the short window)\n- Ophthalmology + rheumatology stat\n- GI prophylaxis PPI + glucose monitoring during high-dose steroid\n\n**Clinical clues:**\n- Age >50 (almost never <50)\n- Jaw claudication (highest LR+)\n- Scalp tenderness, new temporal HA, PMR symptoms (proximal stiffness / shoulder / hip)\n- Constitutional: weight loss, fever, fatigue\n- ESR often >50, CRP almost always up (CRP is more sensitive than ESR)\n- Pale, swollen disc with altitudinal field defect = arteritic AION pattern\n- Amaurosis fugax in the days before frank vision loss is common\n\n**Pitfall:** Do NOT delay steroid for biopsy or test results. Cost of overtreating one false-positive with 3 days of IV steroid is trivial vs cost of a permanent contralateral AION (~30% bilateral rate without treatment).","citation":[5,6,29,30],"recommendation":"Methylpred 1 g IV NOW. ESR/CRP/CBC/plt. Ophtho + rheum stat. Biopsy within 1-2 weeks.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'on-hub-gca' AND tree_id = 'optic-neuropathy-hub';

-- Node: on-hub-ton (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Traumatic Optic Neuropathy","body":"**Next 5 minutes:**\n- CT face + orbits **thin cuts (1 mm bone algorithm)** - thick cuts miss canal fractures\n- Ophthalmology + neurosurgery + oculoplastics stat\n- VA + RAPD + color desat documented at baseline; serial neuro exams\n- Pain control, head of bed up, avoid Valsalva\n- DO NOT give megadose steroid reflexively - CRASH and IOTS data shifted away from routine high-dose methylpred for TBI / TON; institutional decision with consultants\n- Decompression candidates: canalicular fragment + new RAPD + decreasing VA\n\n**Clinical clues:**\n- New RAPD post-trauma is TON until proven otherwise\n- Vision loss may be immediate (direct injury) or delayed (canal hematoma / edema)\n- Often paired with other facial / orbital fractures\n\n**Pitfalls:**\n- Missed canal fracture on thick-cut CT (always ask for thin-cut bone algorithm)\n- Don''t assume the vision loss is \"just orbital edema\" - serial exams matter\n- Do NOT delay neurosurg / oculoplastics consult on the assumption it''s mild","citation":[7,8,31,32],"recommendation":"Thin-cut CT face/orbits. Ophtho + neurosurg + oculoplastics. Serial neuro/VA. Steroid decision is institutional.","confidence":"recommended","safetyLevel":"critical"}'::jsonb
WHERE id = 'on-hub-ton' AND tree_id = 'optic-neuropathy-hub';

-- Node: on-hub-pituitary (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Pituitary Apoplexy","body":"**Next 5 minutes:**\n- **Hydrocortisone 100 mg IV BOLUS now** (then 50 mg IV q6h or 200 mg / 24 h continuous if unstable) - apoplexy = adrenal crisis until proven otherwise; steroid BEFORE imaging\n- Pituitary MRI with gadolinium - dedicated sella cuts (NOT just generic brain MRI)\n- Neurosurgery + endocrinology stat\n- Labs: cortisol, ACTH, TSH, free T4, prolactin, IGF-1, LH, FSH, Na, glucose\n- Visual fields formal once stabilized\n- Replace electrolytes (Na often low), correct glucose, support BP\n\n**Clinical clues:**\n- Sudden severe HA (often retro-orbital or frontal)\n- Visual field defect - classically **bitemporal hemianopia** (chiasm compression) but can be any pattern\n- Ophthalmoplegia (CN III / IV / VI in the cavernous sinus)\n- Hypotension out of proportion to clinical state\n- Hyponatremia, hypoglycemia\n- Predisposing pituitary adenoma (often previously undiagnosed)\n\n**Pitfall:** Missing the adrenal insufficiency and crashing the BP during imaging delays kills more patients than the apoplexy itself.","citation":[9,10],"recommendation":"Hydrocortisone 100 mg IV NOW (BEFORE imaging). Pit MRI + endocrine panel. NSG + endo stat.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'on-hub-pituitary' AND tree_id = 'optic-neuropathy-hub';

-- Node: on-hub-imaging (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Imaging Decision","body":"**MRI brain + orbits WITH gadolinium + fat-saturation orbit sequences** - first-line for:\n- Demyelinating ON\n- Compressive lesions (tumor, mass, sellar / parasellar)\n- Pituitary apoplexy (add dedicated sella cuts)\n- CVST suspicion (add MRV)\n- PRES\n\n**CT face + orbits thin-cut (1 mm bone algorithm)** - first-line for:\n- Trauma -> TON\n- Sinusitis with compression\n- Orbital cellulitis -> [Orbital Cellulitis](#/tree/orbital-cellulitis)\n\n**MRV** - mandatory in:\n- IIH workup (CVST mimics IIH and kills) -> [IIH](#/tree/iih)\n- Pituitary apoplexy with concern for sinus thrombosis\n\n**CTA neck + head** - mandatory when:\n- Horner + pain + monocular vision loss -> [Cervical Artery Dissection](#/tree/cervical-artery-dissection)\n- CRAO (look for embolic source) -> [CRAO](#/tree/crao)\n- Suspected occipital stroke or hemispheric event\n\n**POCUS optic nerve sheath** - bedside ICP screen:\n- Adult cutoff >5 mm at 3 mm posterior to globe\n- Peds >4.5 mm\n- Infant <1 yr >4.0 mm\n- Sensitivity ~90%, specificity ~85% for ICP >20 cm H2O\n- Adjunct only - not a substitute for fundoscopy or LP\n\n**NO imaging for:**\n- Straightforward stable subacute nutritional or drug-induced presentations with confirmed ophtho follow-up within 1 week\n\n**Imaging-not-imaging recall checklist:**\n- Age >50 with new vision loss -> image AND treat as GCA until proven otherwise\n- Any HA + vision change -> MRI / MRV before discharge\n- Trauma -> CT thin-cut, always\n- Bilateral disc swelling -> MRI + MRV, always","citation":[1,4,5,17,19],"next":"on-hub-dispo","summary":"MRI brain+orbits w/gad+fat-sat default. CT trauma/sinus. MRV for IIH/CVST. CTA for Horner/CRAO. ONS US bedside.","safetyLevel":"critical"}'::jsonb
WHERE id = 'on-hub-imaging' AND tree_id = 'optic-neuropathy-hub';

-- Node: pe-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"PE Risk Stratification (2026)","body":"Confirmed or high-probability acute PE. **2026 AHA/ACC categories** replace old massive/submassive terminology.\n\nAssess **hemodynamic status** first:\n• SBP <90 or drop ≥40 mmHg for >15 min?\n• Signs of shock (altered mental status, cool extremities, oliguria)?\n• **Bradycardia (HR <40) = most ominous finding**\n• Bedside echo for RV strain\n• Troponin, BNP, lactate (>2 mM = 10% absolute mortality increase)\n\nUse [PESI](#/calculator/pesi) or [sPESI](#/calculator/spesi) for normotensive patients.","citation":[1,6],"options":[{"label":"Category D-E: Crashing PE","description":"Hypotension, shock, cardiac arrest, or pre-arrest (borderline BP, HR <40)","next":"pe-crashing","urgency":"critical"},{"label":"Category C: Intermediate-Risk","description":"Normotensive with RV dysfunction, elevated biomarkers, or PESI >85","next":"pe-intermediate","urgency":"urgent"},{"label":"Category A-B: Low-Risk","description":"Normal hemodynamics, no RV dysfunction, normal biomarkers, sPESI 0","next":"pe-low-risk"}],"calculatorLinks":[{"id":"pesi","label":"PESI Score"},{"id":"spesi","label":"sPESI Score"},{"id":"pe-risk-category","label":"PE Risk Category (A-E)"}],"summary":"2026 AHA/ACC 5-category system (A-E); assess SBP, RV strain, troponin, lactate; bradycardia <40 = ominous","safetyLevel":"critical"}'::jsonb
WHERE id = 'pe-start' AND tree_id = 'pe-treatment';

-- Node: pa-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Pediatric Appendicitis Overview","body":"See [Steps Summary](#/node/pa-steps-summary) for the rapid-action checklist.\n\n**Why it matters:** [1,2]\n- Most common surgical emergency in children\n- Lifetime incidence ~7%; peak age 10-14\n- Perforation rate in children ~30-40% overall, **>80% in kids <5yo** (delayed/atypical presentation)\n- Missed diagnosis is a top driver of pediatric ED malpractice claims\n\n**Classic presentation (older kids/teens):** [1,3]\n- Periumbilical pain → migration to RLQ (Carnett sign less reliable in kids)\n- Anorexia, nausea, vomiting (vomiting AFTER pain — reverse order suggests gastroenteritis)\n- Low-grade fever (≥38°C)\n- Pain with cough, percussion, or hopping (Markle sign)\n\n**Atypical in younger kids (<5yo):** [2,4]\n- Diffuse abdominal pain or \"won''t bear weight\"\n- Diarrhea (mimics gastroenteritis)\n- Lethargy, irritability\n- May present with perforation/abscess at first ED visit\n- Always re-examine the abdomen — appearance evolves rapidly\n\n**Red flags suggesting perforation or complicated disease:**\n- Diffuse peritonitis, rebound, guarding\n- Fever ≥39°C\n- WBC >18k\n- Symptoms >48h\n- Hemodynamic instability","citation":[1,2,3,4],"next":"pa-history-exam","calculatorLinks":[{"id":"peds-appendicitis-score","label":"PAS Calculator"}],"summary":"Most common peds surgical emergency; perforation rate 30-40% overall and >80% in <5yo; vomit-AFTER-pain is the classic sequence."}'::jsonb
WHERE id = 'pa-start' AND tree_id = 'peds-appendicitis';

-- Node: paa-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Pediatric Acute Asthma Exacerbation","body":"See [Steps Summary](#/node/paa-steps-summary) for the rapid-action checklist.\n\n**Why it matters:** [1,2,3]\n- Asthma is the most common chronic pediatric disease; #1 reason for unscheduled ED visits in school-age children\n- US mortality has declined but still >150 pediatric asthma deaths/year — most preventable, most occurred at home or en route\n- Severe pediatric asthma physiology differs from adults — air trapping is rapid, decompensation is sudden, beta-agonist toxicity is real\n\n**This consult covers:** [3,4]\n1. Triage + **PRAM** scoring (validated 0-12 peds severity score)\n2. Mild-moderate ED treatment ladder (SABA ± ipratropium + dexamethasone)\n3. Severe/life-threatening escalation (continuous SABA, MgSO4, IV terbutaline, heliox, NIV, intubation)\n4. Disposition by PRAM + clinical trajectory\n5. Mimics & beta-agonist toxicity\n\n**EB Medicine pearl:** \"The goal is to avoid intubation — peds asthma intubated mortality is 5-10x higher than adult.\" [3]\n\n**Key differences from adult asthma:** [3,4]\n- Children compensate well, then crash fast — the \"still talking\" 6-year-old can be in impending failure\n- IM/SC epinephrine is safe and underutilized when SABA failing or anaphylaxis component suspected\n- Continuous nebulization is safe and superior to intermittent for severe peds\n- Dexamethasone 0.6 mg/kg PO x 1-2 doses = prednisolone 1-2 mg/kg/d x 5 days for **mild-moderate** [5]","citation":[1,2,3,4,5],"next":"paa-triage","calculatorLinks":[{"id":"pram-score","label":"PRAM Calculator"},{"id":"peds-dose","label":"Peds Dose Calculator"}],"summary":"Peds asthma is the #1 reason for unscheduled ED visits in school-age kids; PRAM 0-12 guides treatment; goal is to avoid intubation.","skippable":true}'::jsonb
WHERE id = 'paa-start' AND tree_id = 'peds-asthma-exacerbation';

-- Node: peds-dka-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Pediatric DKA with Cerebral Edema Protocol","body":"See [Steps Summary](#/node/peds-dka-steps) for the rapid-action checklist.\n\n**Why peds DKA is different from adult DKA:** [1,2,3]\n- **Cerebral edema** is the #1 cause of DKA mortality in children (0.5-0.9% of episodes, 20-25% mortality, 10-25% permanent neuro deficit)\n- Children compensate then crash — the \"looking better\" child who then deteriorates 4-12h into treatment is the classic cerebral edema phenotype\n- Insulin is started AFTER fluids, not concurrently (UK national study: insulin within first hour associated with higher CE risk)\n- The **PECARN FLUID trial** (Kuppermann NEJM 2018, n=1389) overturned old dogma: neither **fluid rate** (fast vs slow) nor **NaCl content** (0.45 vs 0.9%) changed neurologic outcomes [2]\n\n**This consult covers:** [1,3]\n1. ISPAD diagnostic criteria + severity stratification\n2. Fluid resuscitation (PECARN-updated, no bolus dogma)\n3. Insulin therapy timing and dosing\n4. **Cerebral edema recognition (Muir criteria) and emergent treatment**\n5. Resolution criteria and SC insulin transition\n6. [Mimics, complications, and pitfalls](#/node/peds-dka-mimics)\n\n**High-risk for cerebral edema** (consider PICU-level monitoring from the start): [1,5]\n- Age <5 years\n- New-onset diabetes (~30-40% of peds DKA)\n- pH <7.10, pCO2 <21 mmHg, BUN >20 mg/dL\n- Long duration of symptoms before presentation\n- Depressed level of consciousness on arrival","citation":[1,2,3,5],"next":"peds-dka-recognize","calculatorLinks":[{"id":"peds-dka-fluid-calc","label":"DKA Fluid Calculator"},{"id":"muir-cerebral-edema","label":"Muir CE Criteria"},{"id":"peds-dose","label":"Peds Dose Calculator"},{"id":"corrected-na","label":"Corrected Na"}],"summary":"Peds DKA differs from adult: cerebral edema is the #1 killer; insulin starts AFTER 1h of fluids; PECARN showed fluid rate/Na content do not drive CE.","skippable":true}'::jsonb
WHERE id = 'peds-dka-start' AND tree_id = 'peds-dka';

-- Node: pee-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Pediatric Electrolyte Emergencies Overview","body":"See [Steps Summary](#/node/pee-steps-summary) for the rapid-action checklist.\n\n**Why kids are different:** [1,2,3]\n- Higher total body water (75% in neonates vs 60% in adults) → larger fluid shifts with disturbance\n- Lower renal concentrating ability in infants → faster dehydration and electrolyte derangement\n- Cerebral autoregulation immature → faster brain edema with rapid Na shifts\n- Smaller margin of error in dosing — mg/kg matters\n\n**Most common ED presentations:** [1,3]\n- **Hyponatremia:** gastroenteritis given hypotonic fluids, water intoxication in infants, SIADH\n- **Hypernatremia:** dehydration from gastroenteritis, breastfeeding failure neonates, diabetes insipidus\n- **Hyperkalemia:** AKI, hemolysis (spurious vs real), CAH in neonates, drug-induced\n- **Hypokalemia:** vomiting/diarrhea, DKA refeeding, diuretics\n- **Hypocalcemia:** vit D deficiency, hypoparathyroidism, citrate from blood, rhabdo\n- **Hypoglycemia:** sepsis, fasting infants, accidental insulin/sulfonylurea, inborn errors\n\n**Red flags requiring immediate action:** [2,4]\n- Seizure, AMS, lethargy → check glucose AND Na immediately\n- Wide QRS, peaked T → check K immediately\n- Tetany, carpopedal spasm → check Ca and Mg\n- Severe dehydration with shock → balanced crystalloid bolus + electrolyte panel","citation":[1,2,3,4],"next":"pee-triage","summary":"Peds = larger fluid shifts, immature cerebral autoregulation, smaller margin of error; check accucheck + BMP on every altered/seizing child."}'::jsonb
WHERE id = 'pee-start' AND tree_id = 'peds-electrolyte-emergencies';

-- Node: phe-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Pediatric Hypertensive Emergency Overview","body":"See [Steps Summary](#/node/phe-steps-summary) for the rapid-action checklist.\n\n**Definitions (AAP 2017):** [1]\n- **Normal BP:** SBP/DBP <90th %ile for age/sex/height\n- **Elevated BP (formerly pre-HTN):** 90th to <95th %ile, or 120/80 to <95th %ile in adolescents ≥13y\n- **Stage 1 HTN:** 95th %ile to <95th %ile + 12 mmHg, or 130/80 to 139/89 (≥13y)\n- **Stage 2 HTN:** ≥95th %ile + 12 mmHg, or ≥140/90 (≥13y)\n\n**Urgency vs Emergency:** [2,3]\n- **Hypertensive urgency:** severe HTN (typically stage 2 + significant elevation) with **NO** end-organ damage\n- **Hypertensive emergency:** severe HTN **WITH** acute end-organ damage (encephalopathy, seizure, retinopathy, AKI, LV failure)\n\n**ED red-flag thresholds:** [2]\n- BP >99th %ile + 5 mmHg, OR\n- Adolescent: SBP >180 or DBP >120, OR\n- Any BP elevation with symptoms (HA, vomiting, vision change, seizure, AMS)\n\n**Why severe HTN matters in kids:**\n- Adults autoregulate over a wider range — kids decompensate faster\n- Most pediatric severe HTN is **secondary** (renal, cardiac, endocrine) [1,4]\n- Rapid lowering risks watershed infarcts and posterior reversible encephalopathy (PRES) [3]","citation":[1,2,3,4],"next":"phe-confirm-bp","calculatorLinks":[{"id":"map-calculator","label":"MAP Calculator"}],"summary":"Urgency = severe BP without end-organ damage; emergency = severe BP WITH damage; most peds severe HTN is secondary; reduce slowly."}'::jsonb
WHERE id = 'phe-start' AND tree_id = 'peds-hypertensive-emergency';

-- Node: phe-end-organ-eval (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"End-Organ Damage Workup","body":"**Every child with severe HTN needs an end-organ damage screen.** [2,3]\n\n**Neuro:**\n- Mental status, focal deficits, papilledema\n- **Fundoscopy** — flame hemorrhages, exudates, papilledema (hypertensive retinopathy)\n- **Head CT (non-contrast)** if AMS, seizure, focal deficit, severe HA\n- **MRI** preferred for [PRES](#/node/phe-pres) (parieto-occipital edema)\n\n**Cardiac:**\n- **ECG** — LVH (deep S V1 + tall R V5/V6), strain pattern\n- Listen for gallop, murmur (coarctation: harsh systolic ejection at LSB, radiates to back), pulmonary edema\n- Echo if signs of LV failure or coarctation suspected\n\n**Renal:**\n- **Urinalysis** — hematuria, proteinuria, casts (glomerulonephritis)\n- **BMP** — Cr (AKI), K+ (low K in renovascular HTN, primary hyperaldo)\n- Renal U/S with Doppler if renovascular HTN suspected\n\n**Labs to send:** [2]\n- CBC, BMP, urinalysis, urine drug screen, ECG\n- TSH if signs of thyroid disease\n- Plasma renin/aldosterone, metanephrines — usually outpatient workup\n\n**The presence of ANY end-organ damage upgrades to hypertensive emergency.**","citation":[2,3],"next":"phe-classify","summary":"Screen neuro (fundoscopy, head imaging if symptoms), cardiac (ECG for LVH), renal (UA, BMP); ANY end-organ damage = emergency."}'::jsonb
WHERE id = 'phe-end-organ-eval' AND tree_id = 'peds-hypertensive-emergency';

-- Node: pssti-pocus (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Bedside Ultrasound for SSTI","body":"**Point-of-care US (POCUS) outperforms physical exam for abscess detection** — sensitivity 96-98%, specificity 79-89% (Subramaniam 2016, Adams 2016). [4,5]\n\n**Technique pearls:** [4,5]\n- High-frequency **linear probe** (5-12 MHz)\n- Generous gel; scan in 2 orthogonal planes\n- Compare to contralateral side for baseline\n- Use a **standoff pad or copious gel** for small/superficial collections\n\n**Findings:**\n\n| Finding | Implication |\n|---------|-------------|\n| Anechoic fluid collection | Mature abscess — drainable |\n| Hypoechoic with internal debris (\"swirling\") | Abscess; consider I&D |\n| \"Cobblestoning\" (anechoic tracts in subQ fat) | Cellulitis (interstitial edema) — NO abscess |\n| Hyperechoic gas (dirty shadowing, \"snow globe\") | **NSTI suspicion — get surgery NOW** |\n| Fascial thickening / fluid along fascia | Concerning for nec fasc |\n\n**Color Doppler:**\n- Surrounding hyperemia supports inflammation\n- Internal flow argues AGAINST abscess (think pseudoaneurysm, lymph node — get a different study)\n\n**Pitfalls:** [4,5]\n- Lymph nodes look like abscesses on B-mode — check for hilar flow on Doppler\n- Pseudoaneurysm — turbulent flow on Doppler\n- Necrotic tumor — clinical context\n\n**Action:** if POCUS shows abscess → [Purulent pathway](#/node/pssti-purulent). If only cobblestoning → [Cellulitis pathway](#/node/pssti-nonpurulent). If gas in soft tissue → [Necrotizing pathway](#/node/pssti-necfasc) immediately.","citation":[4,5],"next":"pssti-purulent","summary":"POCUS sens ~98% for abscess; linear probe; cobblestoning = cellulitis; gas in soft tissue = NSTI suspicion (get surgery NOW).","skippable":true}'::jsonb
WHERE id = 'pssti-pocus' AND tree_id = 'peds-ssti';

-- Node: pericarditis-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Pericarditis — Diagnostic Criteria","body":"**Diagnosis requires ≥2 of 4 criteria:** [1][2]\n\n| Criterion | Sensitivity |\n|-----------|-------------|\n| **Chest pain** — sharp, pleuritic, positional (better sitting forward) | ~85-90% |\n| **Pericardial friction rub** — scratchy, 3-component (best at LLSB, leaning forward) | ~30% |\n| **ECG changes** — diffuse ST elevation with PR depression | ~60% |\n| **Pericardial effusion** — new or worsening on echo | ~60% |\n\n**Supporting findings:**\n• Elevated inflammatory markers (CRP, ESR, WBC)\n• Elevated troponin suggests myopericarditis\n• Recent viral illness, post-MI, post-cardiac surgery","citation":[1,2,3],"options":[{"label":"Meets ≥2 Criteria — Pericarditis Confirmed","next":"pericarditis-ecg"},{"label":"Only 1 Criterion — Consider Alternatives","description":"ACS, PE, aortic dissection, musculoskeletal","next":"pericarditis-differential"},{"label":"Hemodynamically Unstable","description":"Hypotension, JVD, muffled heart sounds","next":"pericarditis-tamponade","urgency":"critical"}],"calculatorLinks":[{"id":"pericarditis-diagnostic","label":"Diagnostic Criteria"},{"id":"pericarditis-risk","label":"High-Risk Features"}],"summary":"Diagnosis: ≥2 of 4 criteria — chest pain, friction rub, ECG changes, pericardial effusion"}'::jsonb
WHERE id = 'pericarditis-start' AND tree_id = 'pericarditis';

-- Node: pid-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"PID — Clinical Diagnosis","body":"**Pelvic inflammatory disease** is infection of the upper genital tract (uterus, fallopian tubes, ovaries, peritoneum).\n\n**CDC 2021 Minimum Criteria** — treat if ALL present:\n• Sexually active female\n• Pelvic or lower abdominal pain\n• **Cervical motion tenderness**, OR\n• **Uterine tenderness**, OR\n• **Adnexal tenderness** (unilateral or bilateral)\n\nLow threshold to treat — missed PID leads to serious sequelae (infertility, ectopic pregnancy, chronic pelvic pain).","citation":[1,2],"options":[{"label":"Minimum Criteria Met","description":"CMT, uterine, or adnexal tenderness present","next":"pid-additional-criteria"},{"label":"Criteria Not Met","description":"Consider alternative diagnoses","next":"pid-differential"}],"calculatorLinks":[{"id":"pid-criteria","label":"CDC PID Criteria"}],"summary":"CDC minimum: sexually active + pelvic pain + CMT/uterine/adnexal tenderness; low threshold to treat","safetyLevel":"warning"}'::jsonb
WHERE id = 'pid-start' AND tree_id = 'pid';

