-- Node: pid-outpatient-tx (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Outpatient Treatment — CDC 2021","body":"**Recommended regimen:**\n\n**[Ceftriaxone](#/drug/ceftriaxone/pid) 500 mg IM × 1 dose**\n(If weight ≥150 kg: 1 g IM)\n\n**PLUS**\n\n**[Doxycycline](#/drug/doxycycline/pid) 100 mg PO BID × 14 days**\n\n**PLUS**\n\n**[Metronidazole](#/drug/metronidazole/pid) 500 mg PO BID × 14 days**\n\n---\n\n**Metronidazole rationale:**\n• Covers anaerobes and BV organisms\n• CDC recommends adding for all PID (previously optional)\n• Essential if BV on wet prep or TOA concern","citation":[1],"next":"pid-outpatient-f-u","treatment":{"firstLine":{"drug":"Ceftriaxone","dose":"500 mg (1 g if ≥150 kg)","route":"IM","frequency":"Single dose","duration":"One-time injection","notes":"Given in ED before discharge"},"alternative":{"drug":"Doxycycline","dose":"100 mg","route":"PO","frequency":"BID","duration":"14 days","notes":"Add metronidazole 500 mg PO BID × 14 days"},"pcnAllergy":{"drug":"If severe cephalosporin allergy","dose":"Consult ID or CDC guidelines","route":"","frequency":"","duration":"","notes":"May consider azithromycin + metronidazole, but GC coverage less reliable"},"monitoring":"Follow-up in 48-72 hours. If no improvement, admit for IV therapy."},"summary":"Ceftriaxone 500mg IM × 1 + doxycycline 100mg BID × 14d + metronidazole 500mg BID × 14d","safetyLevel":"warning"}'::jsonb
