-- Node: pid-partner-tx (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Partner Treatment","body":"**All sexual partners within past 60 days must be treated.**\n\n**Partner regimen (for GC/CT):**\n• [Ceftriaxone](#/drug/ceftriaxone/gc) 500 mg IM × 1\n• [Doxycycline](#/drug/doxycycline/ct) 100 mg PO BID × 7 days\n\n**Expedited partner therapy (EPT):**\n• Legal in most states\n• Provide prescription or medication for partner(s)\n• Alternative when partner unlikely to seek care\n\n**Counseling:**\n• Partners should be treated even if asymptomatic\n• Abstain until both partners complete treatment\n• Use condoms consistently after treatment\n\n**Reporting:**\n• GC and CT are reportable diseases\n• Health department may assist with partner notification","citation":[1],"next":"pid-disposition","summary":"Treat all partners from past 60 days; EPT is legal option; partners get ceftriaxone 500mg IM + doxy 7 days"}'::jsonb
