-- Node: svt-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"SVT Assessment","body":"**Supraventricular Tachycardia:** Regular, narrow-complex tachycardia originating above the ventricles.\n\n**Common Types:**\n• **AVNRT** (50-60%): Dual AV nodal pathways, pseudo S-wave in II/III/aVF\n• **AVRT** (30%): Accessory pathway (includes WPW), short PR at baseline\n• **Atrial tachycardia** (10%): P-wave before/after QRS\n• **Atrial flutter**: Saw-tooth pattern, typically 150 bpm (2:1 block)\n\n**Typical HR:** 140-250 bpm depending on type\n\n**First Step:** Assess hemodynamic stability.","citation":[1,2],"options":[{"label":"Stable — Proceed with Vagal Maneuvers","next":"svt-vagal-choice"},{"label":"Unstable — Immediate Cardioversion","next":"svt-unstable"},{"label":"Suspected WPW","next":"svt-wpw-assess"}],"summary":"SVT types: AVNRT (50-60%), AVRT (30%), atrial tach (10%), flutter; assess stability first"}'::jsonb
WHERE id = 'svt-start' AND tree_id = 'svt';

-- Node: svt-vagal-choice (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Vagal Maneuver Selection","body":"[Modified Valsalva Technique](#/node/svt-valsalva)\n\n**Vagal maneuvers are first-line for stable SVT (Class I, ACC/AHA 2015).**\n\n**Modified Valsalva (REVERT Trial):**\n• 43% conversion vs 17% standard Valsalva\n• NNT = 3.8\n• Zero-cost, no adverse effects\n\n**Carotid Sinus Massage:**\n• 20-40% success for AVNRT\n• Risk: 1 in 1,000 stroke risk\n• Contraindicated: carotid bruits, recent TIA/stroke, MI <3 months\n\n**Which maneuver?**","citation":[3,4],"options":[{"label":"Modified Valsalva (Preferred)","next":"svt-valsalva"},{"label":"Carotid Sinus Massage","next":"svt-csm"},{"label":"Skip to Adenosine","next":"svt-adenosine"}],"summary":"Vagal maneuvers first-line; modified Valsalva preferred (43% vs 17% conversion)"}'::jsonb
WHERE id = 'svt-vagal-choice' AND tree_id = 'svt';

-- Node: svt-valsalva (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Modified Valsalva Technique (REVERT)","body":"**Technique (REVERT Trial):**\n\n**Step 1:** Patient sitting upright at 45°\n**Step 2:** Blow into 10mL syringe (move plunger) for 15 seconds (~40 mmHg pressure)\n**Step 3:** IMMEDIATELY lie patient flat\n**Step 4:** Elevate legs to 45° for 15 seconds\n**Step 5:** Return to sitting, check rhythm\n\n**Success Rate:** 43% conversion to NSR\n\n**Tips:**\n• Can repeat 2-3 times\n• Works best for AVNRT and AVRT\n• Patient may feel brief chest pressure during maneuver\n\n**Did the rhythm convert?**","citation":[3],"options":[{"label":"Yes — Converted to NSR","next":"svt-converted"},{"label":"No — Proceed to Adenosine","next":"svt-adenosine"}],"summary":"REVERT: blow into syringe 15s → immediately flat → legs up 15s; 43% success"}'::jsonb
WHERE id = 'svt-valsalva' AND tree_id = 'svt';

-- Node: svt-adenosine (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Adenosine Administration","body":"**Dosing:**\n• **Initial:** 6mg rapid IV push (1-2 seconds)\n• **Repeat:** 12mg if no response in 1-2 minutes\n• **Max:** 12mg × 2 (some sources allow 18mg)\n\n**Administration Technique (Critical):**\n1. Use proximal IV (antecubital preferred)\n2. Rapid bolus over 1-2 seconds (half-life ~10 seconds)\n3. Immediately follow with 20mL NS flush\n4. Optional: elevate arm to 90° for 10-20 seconds\n\n**Single-Syringe Method:**\n• 6mg adenosine + 18mL NS in one syringe\n• Higher success (100% with up to 3 doses vs 70% two-syringe)\n\n**Dose Modifications:**\n• **Reduce to 3mg:** Central line, transplanted heart, carbamazepine, dipyridamole\n• **Increase to 12mg:** Theophylline, high caffeine intake\n\n**Pediatric:** 0.1 mg/kg initial, 0.2 mg/kg repeat","citation":[1,5],"next":"svt-adenosine-response","summary":"6mg rapid IV push + 20mL flush; repeat 12mg if needed; reduce to 3mg for central line"}'::jsonb
WHERE id = 'svt-adenosine' AND tree_id = 'svt';

-- Node: svt-rate-control (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":4,"title":"Rate Control Options","body":"**If adenosine fails or SVT recurs, rate control agents are next.**\n\n**Diltiazem (Preferred):**\n• 15-20mg (0.25 mg/kg) IV over 2 minutes\n• Repeat 20-25mg (0.35 mg/kg) in 15 min if needed\n• Infusion: 5-15 mg/hr\n• **98% reach target HR; 50% at 5 min**\n• Caution: more hypotension than metoprolol (39% vs 24%)\n\n**Metoprolol:**\n• 5mg IV every 5 minutes × 3 doses (max 15mg)\n• Slower onset but less hypotension\n\n**Amiodarone (if above fail):**\n• 150mg IV over 10-15 minutes\n• Infusion: 1 mg/min × 6h, then 0.5 mg/min\n\n**Which agent?**","citation":[1,6],"options":[{"label":"Diltiazem (First-Line)","next":"svt-diltiazem"},{"label":"Metoprolol","next":"svt-metoprolol"},{"label":"Amiodarone (Refractory)","next":"svt-amiodarone"}],"summary":"Diltiazem preferred (98% success, faster onset); metoprolol if hypotension concern; amiodarone if refractory"}'::jsonb
WHERE id = 'svt-rate-control' AND tree_id = 'svt';

-- Node: svt-diltiazem (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Diltiazem for SVT","body":"**Initial Bolus:**\n• 15-20mg (0.25 mg/kg) IV over 2 minutes\n• Flush with saline\n\n**Repeat Bolus (if needed):**\n• 20-25mg (0.35 mg/kg) IV in 15 minutes\n\n**Maintenance Infusion:**\n• 5-15 mg/hr (titrate to HR <100)\n• Start at 5 mg/hr, increase as needed\n\n**Response:**\n• 50% reach HR <100 by 5 minutes\n• 95% reach target by 30 minutes\n• 98% overall success\n\n**Monitor For:**\n• Hypotension (39% experience drop)\n• Bradycardia\n• AV block\n\n**Contraindications:**\n• WPW with pre-excited AF\n• Hypotension (SBP <90)\n• Severe LV dysfunction\n• Sick sinus syndrome\n\n**If converted → disposition. If rate controlled → consider admission vs discharge based on context.**","citation":[6],"recommendation":"Diltiazem 15-20mg IV over 2 min, repeat 20-25mg if needed. Infusion 5-15 mg/hr. 98% success.","confidence":"recommended","summary":"Diltiazem 15-20mg IV bolus, repeat 20-25mg; infusion 5-15 mg/hr; 98% success, 50% at 5 min"}'::jsonb
WHERE id = 'svt-diltiazem' AND tree_id = 'svt';

-- Node: svt-unstable (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Unstable SVT — Cardioversion","body":"**Indications for Immediate Cardioversion:**\n• Hypotension (SBP <90)\n• Altered mental status\n• Chest pain/ischemic ECG changes\n• Pulmonary edema\n• Signs of shock\n\n**Do NOT delay for vagal maneuvers or adenosine if truly unstable.**\n\n**Synchronized Cardioversion Protocol:**\n\n**1. Sedation (if time permits):**\n• Propofol 0.5-1 mg/kg IV, OR\n• Etomidate 0.2-0.3 mg/kg IV, OR\n• Midazolam 0.05-0.1 mg/kg IV + fentanyl\n\n**2. Energy Selection (Narrow Complex):**\n• **Start: 50-100J**\n• Escalate: 100 → 200 → 360J if unsuccessful\n\n**3. Ensure SYNC mode is ON**\n\n**4. Clear patient and deliver shock**\n\n**Pediatric:** 0.5-2 J/kg","citation":[1,8],"next":"svt-cardiovert-result","summary":"Unstable = hypotension, AMS, chest pain, pulmonary edema; sedate → synchronized cardioversion 50-100J"}'::jsonb
WHERE id = 'svt-unstable' AND tree_id = 'svt';

-- Node: svt-wpw-assess (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":6,"title":"WPW Assessment","body":"**Wolff-Parkinson-White Syndrome:**\nAccessory pathway bypasses AV node → risk of rapid conduction in AF/flutter.\n\n**Baseline ECG Clues:**\n• Short PR interval (<120ms)\n• Delta wave (slurred QRS upstroke)\n• Wide QRS (>120ms)\n\n**WPW + SVT Presentation:**\n\n**Orthodromic AVRT (90%):**\n• Narrow complex (antegrade through AV node)\n• AV nodal blockers may be used cautiously\n\n**Antidromic AVRT (10%):**\n• Wide complex (antegrade through accessory pathway)\n• Avoid AV nodal blockers\n\n**WPW + Atrial Fibrillation:**\n• Irregular, wide complex, very fast (>200 bpm)\n• **MOST DANGEROUS — AV nodal blockers can cause VF**\n\n**What is the presentation?**","citation":[9,10],"options":[{"label":"Narrow Complex (Orthodromic AVRT)","next":"svt-wpw-orthodromic"},{"label":"Wide Complex / Pre-excited AF","next":"svt-wpw-af"}],"summary":"WPW: short PR, delta wave; orthodromic = narrow (safe for AV blockers); pre-excited AF = AVOID AV blockers"}'::jsonb
WHERE id = 'svt-wpw-assess' AND tree_id = 'svt';

-- Node: svt-wpw-af (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":6,"title":"WPW + Pre-excited AF — DANGER","body":"**⚠️ THIS IS A CRITICAL DIAGNOSIS**\n\n**ECG Features:**\n• Irregular rhythm (AF)\n• Very fast (often >200 bpm)\n• Wide QRS (pre-excited)\n• Variable QRS morphology\n\n**🚫 AVOID THESE DRUGS (can cause VF):**\n• Adenosine\n• Diltiazem/Verapamil\n• Beta-blockers\n• Digoxin\n\n**Why dangerous:** AV nodal blockers remove the \"brakes\" — AF conducts rapidly down accessory pathway → VF\n\n**✅ SAFE TREATMENTS:**\n\n**1. Synchronized Cardioversion (preferred if unstable):**\n• 100-200J synchronized\n\n**2. Procainamide (if stable):**\n• 20-50 mg/min IV (max 17 mg/kg)\n• Slows accessory pathway conduction\n\n**3. Ibutilide:**\n• 1mg IV over 10 min\n• Can repeat once\n\n**Admission:** All WPW + AF requires cardiology consult and admission.","citation":[9,10],"recommendation":"WPW + AF: AVOID adenosine/diltiazem/beta-blockers. Cardiovert if unstable. Procainamide if stable.","confidence":"definitive","summary":"WPW + pre-excited AF: AVOID AV nodal blockers (causes VF); cardiovert or procainamide; admit for EP"}'::jsonb
WHERE id = 'svt-wpw-af' AND tree_id = 'svt';

-- Node: te-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Terrestrial Envenomations Overview","body":"See [Steps Summary](#/node/te-steps-summary) for rapid-action checklist.\n\n**Scope:** Non-snake, non-marine envenomations seen in the US ED. [1,2]\n- **Spiders:** Black widow (*Latrodectus*), brown recluse (*Loxosceles*), hobo, tarantula\n- **Scorpions:** Bark scorpion (*Centruroides sculpturatus*, AZ/NM/southern CA)\n- **Hymenoptera:** Bees, wasps, hornets, fire ants — leading cause of envenomation deaths in US (anaphylaxis)\n- **Other:** Centipedes, millipedes, kissing bugs, blister beetles\n\n**Why it matters:** [1,3]\n- ~50 hymenoptera anaphylaxis deaths/year in US — most preventable with rapid IM epi\n- *Centruroides* envenomation in peds can cause respiratory failure; Anascorp dramatically reduces ICU time (Boyer 2009 NEJM)\n- *Loxosceles* systemic loxoscelism (hemolysis, DIC) occurs in <10% but carries high mortality if missed\n- Black widow envenomation mimics acute abdomen and is commonly misdiagnosed\n\n**Initial priorities:**\n1. **ABCs + anaphylaxis screen** — most deaths are from hymenoptera anaphylaxis, not direct venom toxicity\n2. **Identify the organism** by geography, exposure, and lesion pattern\n3. **Risk-stratify** for systemic effects (vital signs, neuro exam, CBC/CMP/CK as indicated)\n4. **Targeted antivenom** if appropriate (*Centruroides* grade III-IV, severe widow)","citation":[1,2,3],"next":"te-triage","summary":"Spider, scorpion, hymenoptera envenomations. Hymenoptera anaphylaxis kills most. Anascorp dramatically reduces peds scorpion ICU time. Loxoscelism <10% but deadly."}'::jsonb
WHERE id = 'te-start' AND tree_id = 'terrestrial-envenomation';

-- Node: tox-alc-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Toxic Alcohols — Initial Assessment","body":"**The toxic alcohols are:**\n• **Methanol** — windshield washer fluid, paint thinner, moonshine\n• **Ethylene glycol** — antifreeze (sweet taste), brake fluid\n• **Isopropyl alcohol** — rubbing alcohol, hand sanitizer\n• **Propylene glycol** — IV drug diluent (lorazepam, phenytoin, esmolol)\n\n**Key clinical concept:**\nThe parent compounds cause intoxication. The **metabolites** cause organ damage [1][2].\n• Methanol → **formic acid** → retinal/optic nerve toxicity, blindness\n• Ethylene glycol → **glycolic/oxalic acid** → renal failure, Ca-oxalate crystals\n• Isopropyl alcohol → **acetone** → minimal end-organ toxicity\n\n**Treatment goals:** Block alcohol dehydrogenase to prevent toxic metabolite formation.\n\nWhat is the patient''s current clinical status?","citation":[1,2],"options":[{"label":"Suspected ingestion — asymptomatic","description":"History of ingestion, no symptoms yet","next":"tox-alc-identify"},{"label":"Inebriated with unknown ingestion","description":"CNS depression, unclear what was ingested","next":"tox-alc-identify"},{"label":"Anion gap metabolic acidosis","description":"Known or suspected toxic alcohol with acidosis","next":"tox-alc-severe","urgency":"urgent"},{"label":"Vision changes or seizures","description":"Likely methanol toxicity — emergent treatment","next":"tox-alc-methanol-severe","urgency":"critical"},{"label":"Renal failure + acidosis","description":"Likely ethylene glycol — emergent treatment","next":"tox-alc-eg-severe","urgency":"critical"}],"calculatorLinks":[{"id":"tox-alc-osmolar","label":"Osmolar Gap Calculator"}],"summary":"Parent compounds cause intoxication; metabolites cause organ damage — methanol→blindness, EG→renal failure","safetyLevel":"warning"}'::jsonb
WHERE id = 'tox-alc-start' AND tree_id = 'toxic-alcohols';

-- Node: tox-alc-methanol-severe (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Severe Methanol Toxicity — Emergent Treatment","body":"**CRITICAL: Vision changes indicate formic acid accumulation — irreversible damage occurring NOW**\n\n**Immediate actions (do all simultaneously):**\n1. **[Fomepizole](#/drug/fomepizole/methanol)** 15 mg/kg IV loading dose — blocks alcohol dehydrogenase [1][4]\n2. **Nephrology consult for urgent hemodialysis** — removes methanol AND formic acid [1][4]\n3. **Folic acid** 50 mg IV Q4-6H — enhances formic acid metabolism [1][3]\n4. **Sodium bicarbonate** if pH <7.3 — maintain pH >7.3 to reduce formate toxicity\n\n**Dialysis indications for methanol [EXTRIP]:**\n• Methanol >70 mg/dL (or >50 mg/dL with severe acidosis)\n• Vision changes\n• Coma or seizures\n• Severe metabolic acidosis despite treatment\n• Renal dysfunction\n\n**Goal:** Stop metabolite production and remove formic acid before permanent blindness.","citation":[1,3,4],"next":"tox-alc-fomepizole","calculatorLinks":[{"id":"tox-alc-fomepizole","label":"Fomepizole Dosing"}],"summary":"Vision changes = formic acid damage NOW; fomepizole + urgent HD + folic acid; dialysis if methanol >50-70 mg/dL or vision symptoms","safetyLevel":"critical"}'::jsonb
WHERE id = 'tox-alc-methanol-severe' AND tree_id = 'toxic-alcohols';

-- Node: tox-alc-cofactors (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Cofactor Therapy","body":"**Cofactors enhance metabolism of toxic metabolites:**\n\n**METHANOL:**\n• **Folic acid** 50 mg IV Q4-6H (max 50 mg/dose)\n• OR **Folinic acid (leucovorin)** 50-100 mg IV Q4H (preferred over folic acid when available; EMCrit IBCC 2025)\n• **Mechanism:** Enhances formate → CO₂ + H₂O conversion via tetrahydrofolate pathway [1][3]\n• Continue until methanol <20 mg/dL\n\n**ETHYLENE GLYCOL:**\n• **[Thiamine](#/drug/thiamine/eg)** 100 mg IV Q6H\n• **[Pyridoxine (B6)](#/drug/pyridoxine/eg)** 100 mg IV Q6H\n• **Mechanism:** Shunt glyoxylic acid away from oxalic acid toward glycine and alpha-hydroxy-beta-ketoadipate [1][2]\n• Reduces nephrotoxicity from calcium-oxalate precipitation\n\n**ALCOHOLIC PATIENTS (risk of Wernicke):**\n• High-dose thiamine: 200-500 mg IV Q8H × 72+ hours\n• Give BEFORE glucose (risk of precipitating Wernicke)","citation":[1,2,3],"next":"tox-alc-bicarb","treatment":{"firstLine":{"drug":"Folic Acid (methanol)","dose":"50 mg","route":"IV","frequency":"Q4-6H","duration":"Until methanol <20 mg/dL","notes":"Enhances formate metabolism. Use for methanol specifically."},"alternative":{"drug":"Thiamine + Pyridoxine (EG)","dose":"100 mg each","route":"IV","frequency":"Q6H","duration":"Until EG cleared","notes":"Shunts glyoxylic acid away from oxalate formation."},"monitoring":"Toxic alcohol levels. Renal function for EG."},"summary":"Methanol: folic acid 50mg IV Q4-6H; EG: thiamine 100mg + pyridoxine 100mg IV Q6H; alcoholics: high-dose thiamine 200-500mg Q8H"}'::jsonb
WHERE id = 'tox-alc-cofactors' AND tree_id = 'toxic-alcohols';

COMMIT;